 18→use std::sync::{Arc, Mutex};
 19→
 20→use adbc_client::AdbcConnection;
 21→use test_framework::{
 22→    anyhow,
 23→    execution::{ExecutionResult, QueryExecutor},
 24→};
 25→
 26→/// Executes queries directly against a database via ADBC.
 27→///
 28→/// `AdbcConnection` is not `Send`/`Sync` (the underlying `ManagedConnection`
 29→/// uses raw FFI pointers), so we wrap it in `Arc<Mutex<>>` to satisfy the
 30→/// `Send + Sync` bounds required by [`QueryExecutor`] and to allow cloning
 31→/// the executor across concurrent tasks.
 32→pub(crate) struct AdbcDirectQueryExecutor {
 33→    conn: Arc<Mutex<AdbcConnection>>,
 34→}
 35→
 36→impl AdbcDirectQueryExecutor {
 37→    pub(crate) fn new(conn: AdbcConnection) -> Self {
 38→        Self {
 39→            conn: Arc::new(Mutex::new(conn)),
 40→        }
 41→    }
 42→
 43→    pub(crate) fn from_shared(conn: Arc<Mutex<AdbcConnection>>) -> Self {
 44→        Self { conn }
 45→    }
 46→}
 47→
 48→impl Clone for AdbcDirectQueryExecutor {
 49→    fn clone(&self) -> Self {
 50→        Self {
 51→            conn: Arc::clone(&self.conn),
 52→        }
 53→    }
 54→}
 55→
 56→#[async_trait::async_trait]
 57→impl QueryExecutor for AdbcDirectQueryExecutor {
 58→    async fn execute(
 59→        &self,
 60→        query: &test_framework::queries::Query,
 61→    ) -> anyhow::Result<ExecutionResult> {
 62→        let sql = query.to_sql_with_inlined_params().to_string();
 63→        let conn = Arc::clone(&self.conn);
 64→
 65→        // `AdbcConnection::query()` is synchronous (ADBC has no async API),
 66→        // so we run it on the blocking thread pool to avoid stalling the tokio runtime.
 67→        let (duration, batches) = tokio::task::spawn_blocking(move || {
 68→            let start = std::time::Instant::now();
 69→            let mut guard = conn
 70→                .lock()
 71→                .map_err(|e| anyhow::anyhow!("Lock poisoned: {e}"))?;
 72→            let batches = guard.query(&sql).map_err(|e| anyhow::anyhow!("{e}"))?;
 73→            Ok::<_, anyhow::Error>((start.elapsed(), batches))
 74→        })
 75→        .await??;
 76→
 77→        let row_count: usize = batches
 78→            .iter()
 79→            .map(arrow::array::RecordBatch::num_rows)
 80→            .sum();
 81→
 82→        Ok(ExecutionResult {
 83→            duration,
 84→            row_count,
 85→            batches: Some(batches),
 86→        })
 87→    }
 88→
 89→    fn name(&self) -> &'static str {
 90→        "adbc_direct"
 91→    }
 92→
 93→    fn supports_validation(&self) -> bool {
 94→        true
 95→    }
 96→
 97→    fn clone_box(&self) -> Box<dyn QueryExecutor> {
 98→        Box::new(self.clone())
 99→    }
100→}
