 38→pub(crate) fn create_telemetry_with_resource(common: &CommonArgs, resource: Resource) -> Telemetry {
 39→    if let Some(endpoint) = &common.otlp_endpoint {
 40→        return Telemetry::with_otlp_resource(
 41→            OtlpExporterConfig {
