 53→/// Build a test configuration with validation data if applicable
 54→///
 55→/// This is a common helper for bench, throughput, and load tests that:
 56→/// 1. Loads the query set from args
 57→/// 2. Applies query overrides if specified
 58→/// 3. Adds validation data for scenario queries when validation is enabled
 59→/// 4. Adds reference schema for validation against known good tables
 60→///
 61→/// # Returns
 62→/// Tuple of (`QuerySet`, `NotStarted` builder)
 63→#[allow(dead_code)]
 64→pub(crate) async fn build_test_with_validation(
 65→    scenario: &Scenario,
 66→    test_builder: NotStarted,
 67→) -> anyhow::Result<(QuerySet, NotStarted)> {
 68→    let query_set = scenario.load_query_set()?;
 69→    let queries = query_set.get_queries(None, None, None).await?;
 70→
 71→    let test_builder = test_builder
 72→        .with_query_set(queries)
 73→        .with_query_set_type(query_set.clone());
 74→
 75→    Ok((query_set, test_builder))
 76→}
