 78→/// Connect to a system adapter based on command-line arguments
 79→///
 80→/// All validation is handled by clap:
 81→/// - `conflicts_with` ensures stdio and http aren't both set
 82→/// - `requires` ensures params/args/env need a transport
 83→/// - `group` allows either stdio or http transport
 84→pub async fn connect_system_adapter(args: &CommonArgs) -> anyhow::Result<SystemAdapterClient> {
 85→    if let Some(command) = &args.system_adapter_stdio_cmd {
 86→        let args_vec = args
 87→            .system_adapter_stdio_args
 88→            .as_ref()
 89→            .map(|s| s.split_whitespace().map(String::from).collect())
 90→            .unwrap_or_default();
 91→
 92→        return ClientBuilder::stdio(command)
 93→            .with_args(args_vec)
 94→            .with_env(args.system_adapter_env.clone().into_iter().collect())
 95→            .build()
 96→            .map_err(|e| anyhow::anyhow!("Failed to create stdio client: {e}"));
 97→    }
 98→
 99→    if let Some(endpoint) = &args.system_adapter_http_url {
100→        return ClientBuilder::http(endpoint)
101→            .build()
102→            .map_err(|e| anyhow::anyhow!("Failed to create HTTP client: {e}"));
103→    }
104→
105→    Err(anyhow::anyhow!("No system adapter transport configured"))
106→}
