 43→fn create_tables_request_datasets(
 44→    dataset: &Arc<dyn Dataset>,
 45→    with_created_at: bool,
 46→) -> HashMap<String, system_adapter_protocol::DatasetConfig> {
 47→    dataset
 48→        .tables()
 49→        .into_iter()
 50→        .map(|(name, table)| {
 51→            let schema = if with_created_at {
 52→                let mut fields: Vec<_> = table.schema.fields().iter().cloned().collect();
 53→                fields.push(Arc::new(Field::new(
 54→                    "__created_at",
 55→                    DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into())),
 56→                    true,
 57→                )));
 58→                Arc::new(Schema::new(fields))
 59→            } else {
 60→                table.schema.clone()
 61→            };
 62→
 63→            (name, system_adapter_protocol::DatasetConfig { schema })
 64→        })
 65→        .collect()
 66→}
