 81→async fn run_benchmark(
 82→    common: &CommonArgs,
 83→    system_adapter_client: &mut system_adapter_protocol::Client,
 84→    run_id: uuid::Uuid,
 85→    adbc_driver: system_adapter_protocol::SetupResponse,
 86→    dataset_source: DatasetSource,
 87→    generation_config: &GenerationDatasetConfig,
 88→    mutations: &MutationConfig,
 89→    source: Arc<S3Storage>,
 90→    datasets: HashMap<String, system_adapter_protocol::DatasetConfig>,
 91→) -> anyhow::Result<()> {
 92→    // --- Download checkpoints from S3 ---
 93→    let scenario_name = common.scenario.to_string();
 94→    let checkpoint_dir = tempfile::tempdir()?;
 95→
 96→    let checkpoint_store = CheckpointStore::new(
 97→        &common.etl_bucket,
 98→        &common.etl_source_prefix,
 99→        common.etl_region.as_deref(),
100→        common.etl_endpoint.as_deref(),
101→    )?;
102→
103→    let manifest = checkpoint_store.download_manifest().await.map_err(|e| {
104→        tracing::warn!("Failed to download checkpoint manifest - results validation will not be enabled: {e}");
105→        e
106→    }).ok();
107→    let mut checkpoint_steps: Option<usize> = None;
108→    if let Some(manifest) = manifest
109→        && let Some(scenario_info) = manifest.scenarios.get(&scenario_name)
110→    {
111→        tracing::info!(
112→            scenario = %scenario_name,
113→            num_checkpoints = scenario_info.checkpoint_indexes.len(),
114→            num_queries = scenario_info.query_indexes.len(),
115→            checkpoint_interval_steps = scenario_info.checkpoint_interval_steps,
116→            path = %checkpoint_dir.path().display(),
117→            "Downloading checkpoints"
118→        );
119→        if scenario_info.checkpoint_interval_steps > 0 {
120→            checkpoint_steps = Some(scenario_info.checkpoint_interval_steps);
121→        }
122→        if let Err(e) = checkpoint_store
123→            .download_checkpoints(&scenario_name, scenario_info, checkpoint_dir.path())
124→            .await
125→        {
126→            tracing::warn!(
127→                "Failed to download checkpoints - results validation will not be enabled: {e}"
128→            );
129→        } else {
130→            tracing::info!(scenario = %scenario_name, "Checkpoints downloaded");
131→        }
132→    } else {
133→        tracing::warn!(
134→            scenario = %scenario_name,
135→            "No checkpoints found for scenario in manifest"
136→        );
137→    }
138→
139→    let driver_name = adbc_driver.driver.to_string();
140→    let sink_kwargs = adbc_driver.db_kwargs.clone();
141→    let load_kwargs = adbc_driver.db_kwargs;
142→
143→    let adbc_conn = AdbcConnection::create(&driver_name, sink_kwargs).map_err(|e| {
144→        anyhow::anyhow!(
145→            "Failed to create ADBC connection for driver {}: {e}",
146→            driver_name
147→        )
148→    })?;
149→    println!("ADBC connection established (driver: {})", driver_name);
150→
151→    let target = Arc::new(AdbcSink::new_without_table_creation(adbc_conn, None));
152→    let mut pipeline =
153→        ETLPipeline::new(dataset_source, generation_config, source, target, mutations)?
154→            .with_created_at(common.with_created_at);
155→
156→    if let Err(e) = system_adapter_client.create_tables(run_id, datasets).await {
157→        pipeline.cancel();
158→        return Err(anyhow::anyhow!(
159→            "Failed to create tables via system adapter: {e}"
160→        ));
161→    }
162→
163→    // --- Initialize: ETL the first batch so the target has data ---
164→    tracing::info!("Initializing ETL pipeline (first batch)...");
165→    pipeline.initialize().await?;
166→    tracing::info!("ETL pipeline initialized");
167→
168→    let load_conn = match AdbcConnection::create(&driver_name, load_kwargs) {
169→        Ok(conn) => conn,
170→        Err(e) => {
171→            pipeline.cancel();
172→            return Err(anyhow::anyhow!(
173→                "Failed to create benchmark ADBC connection for driver {}: {e}",
174→                driver_name
175→            ));
176→        }
177→    };
178→
179→    commands::load::run(
180→        &common.scenario,
181→        common,
182→        load_conn,
183→        &mut pipeline,
184→        checkpoint_steps,
185→    )
186→    .await?;
187→
188→    // --- Wait for ETL to finish ---
189→    // If checkpoint_steps was set, the load runner already handled
190→    // the pause/resume loop internally, so the pipeline should be
191→    // in a stopped state by now. If it was started without checkpoints
192→    // (.start()), the pipeline may still be running.
193→    let final_state = pipeline.wait().await;
194→    match &final_state {
195→        PipelineState::Stopped(StopReason::Completed) => {
196→            tracing::info!("ETL pipeline completed successfully");
197→        }
198→        PipelineState::Stopped(StopReason::Cancelled) => {
199→            tracing::warn!("ETL pipeline was cancelled");
200→        }
201→        PipelineState::Stopped(StopReason::Error(e)) => {
202→            tracing::error!(error = %e, "ETL pipeline stopped with error");
203→        }
204→        other => {
205→            tracing::warn!("Unexpected final pipeline state: {other:?}");
206→        }
207→    }
208→
209→    Ok(())
210→}
