212→#[tokio::main]
213→async fn main() -> anyhow::Result<()> {
214→    let _ = rustls::crypto::CryptoProvider::install_default(
215→        rustls::crypto::aws_lc_rs::default_provider(),
216→    );
217→
218→    tracing_subscriber::fmt()
219→        .with_max_level(Level::INFO)
220→        .with_env_filter(EnvFilter::from_default_env())
221→        .init();
222→
223→    let cli = Cli::parse();
224→
225→    // --- Construct the ETL pipeline ---
226→    let dataset_source = match &cli.common.scenario {
227→        Scenario::TPCH => DatasetSource::Tpch,
228→    };
229→
230→    let generation_config = GenerationDatasetConfig {
231→        dataset_type: match &dataset_source {
232→            DatasetSource::Tpch => "tpch".to_string(),
233→            DatasetSource::SimpleSequence => "simple_sequence".to_string(),
234→        },
235→        scale_factor: cli.common.scale_factor,
236→        num_steps: cli.common.etl_num_steps,
237→    };
238→
239→    let source_config = TargetConfig {
240→        bucket: cli.common.etl_bucket.clone(),
241→        prefix: cli.common.etl_source_prefix.clone(),
242→        region: cli.common.etl_region.clone(),
243→        endpoint: cli.common.etl_endpoint.clone(),
244→    };
245→
246→    let source = Arc::new(S3Storage::new(&source_config)?);
247→
248→    // --- Connect to the system adapter ---
249→    let mut system_adapter_client = match connect_system_adapter(&cli.common).await {
250→        Ok(system_adapter_client) => system_adapter_client,
251→        Err(e) => {
252→            return Err(anyhow::anyhow!("Failed to connect to system adapter: {e}"));
253→        }
254→    };
255→
256→    let run_id = uuid::Uuid::new_v4();
257→    let mutations = MutationConfig::new(0.0, 0.0);
258→
259→    let setup_dataset = dataset_source.create(
260→        &generation_config,
261→        &mutations,
262→        Arc::clone(&source) as Arc<dyn DataStorage>,
263→    )?;
264→    let datasets = create_tables_request_datasets(&setup_dataset, cli.common.with_created_at);
265→
266→    let setup_metadata = std::collections::HashMap::from([
267→        (
268→            "executor_instance_type".to_string(),
269→            serde_json::Value::String(cli.common.executor_instance_type.clone()),
270→        ),
271→        (
272→            "table_format".to_string(),
273→            serde_json::Value::String(cli.common.table_format.to_string()),
274→        ),
275→    ]);
276→
277→    let adbc_driver = match system_adapter_client.setup(run_id, setup_metadata).await {
278→        Ok(response) => response,
279→        Err(e) => {
280→            return Err(anyhow::anyhow!("Failed to setup system adapter: {e}"));
281→        }
282→    };
283→
284→    let result = run_benchmark(
285→        &cli.common,
286→        &mut system_adapter_client,
287→        run_id,
288→        adbc_driver,
289→        dataset_source,
290→        &generation_config,
291→        &mutations,
292→        source,
293→        datasets,
294→    )
295→    .await;
296→
297→    // After successful setup, always teardown even if there are errors in between.
298→    if let Err(e) = system_adapter_client.teardown(run_id).await {
299→        tracing::error!("Failed to teardown system adapter: {e}");
300→    }
301→
302→    result
303→}
