 56→    bucket: String,
 57→
 58→    /// S3 key prefix for source data
 59→    #[arg(long, default_value = "")]
 60→    source_prefix: String,
 61→    /// AWS region
 62→    #[arg(long)]
 63→    region: Option<String>,
