 65→    /// S3 endpoint URL (for MinIO/LocalStack)
 66→    #[arg(long)]
 67→    endpoint: Option<String>,
 68→
 69→    /// Path to the local DuckDB database file to sink data into
 70→    #[arg(long)]
 71→    duckdb_path: PathBuf,
 72→
 73→    /// Every N steps to take a checkpoint
 74→    #[arg(long, default_value_t = 100)]
 75→    checkpoint_interval_steps: u64,
