115→/// Run all checkpoint queries against the DuckDB sink and write each result
116→/// set to a parquet file at `<checkpoint_dir>/<checkpoint_idx>/<query_idx>.parquet`.
117→async fn run_checkpoint_queries(
118→    sink: &DuckDBSink,
119→    checkpoint_queries: &[String],
120→    checkpoint_dir: &Path,
121→    checkpoint_idx: usize,
122→) -> anyhow::Result<()> {
123→    let resolved_checkpoint_dir = checkpoint_dir.join(checkpoint_idx.to_string());
124→    fs::create_dir_all(&resolved_checkpoint_dir)?;
125→
126→    for (query_idx, sql) in checkpoint_queries.iter().enumerate() {
127→        tracing::info!(
128→            checkpoint = checkpoint_idx,
129→            query = query_idx,
130→            "Running checkpoint query"
131→        );
132→
133→        let batches = sink.query(sql).await?;
134→        let out_path = resolved_checkpoint_dir.join(format!("{query_idx}.parquet"));
135→
136→        // Derive the result schema. If the query returned rows, use the first
137→        // batch's schema. Otherwise, ask DuckDB for the schema directly — this
138→        // works even when zero rows are returned.
139→        let result_schema = if let Some(first) = batches.first() {
140→            first.schema()
141→        } else {
142→            sink.query_schema(sql).await?
143→        };
144→
145→        let total_rows: usize = batches.iter().map(|b| b.num_rows()).sum();
146→        write_batches_to_parquet(&batches, &out_path, &result_schema)?;
147→
148→        tracing::info!(
149→            checkpoint = checkpoint_idx,
150→            query = query_idx,
151→            rows = total_rows,
152→            path = %out_path.display(),
153→            "Checkpoint query result written"
154→        );
155→    }
156→
157→    Ok(())
158→}
159→
160→/// Write a slice of `RecordBatch`es to a single parquet file.
161→///
162→/// If `batches` is empty (the query returned zero rows) an empty parquet file
163→/// containing only the schema from `result_schema` is written.
164→fn write_batches_to_parquet(
165→    batches: &[RecordBatch],
166→    path: &Path,
167→    result_schema: &arrow::datatypes::SchemaRef,
168→) -> anyhow::Result<()> {
169→    let file = fs::File::create(path)?;
170→    let mut writer = ArrowWriter::try_new(file, Arc::clone(result_schema), None)?;
171→    for batch in batches {
172→        writer.write(batch)?;
173→    }
174→    writer.close()?;
175→    Ok(())
176→}
177→
178→#[tokio::main]
179→async fn main() -> anyhow::Result<()> {
180→    tracing_subscriber::fmt()
181→        .with_env_filter(EnvFilter::from_default_env())
182→        .init();
183→
184→    let cli = Cli::parse();
185→
186→    let scenario_name = cli.scenario.to_string();
187→    let query_set = cli.scenario.load_query_set()?;
188→    let checkpoint_queries: Vec<String> = query_set
189→        .get_queries(None, None, None)
190→        .await?
191→        .iter()
192→        .map(|q| q.sql.to_string())
193→        .collect();
194→
195→    let dataset_source = cli.dataset_source()?;
196→    let dataset_config = cli.dataset_config();
197→
198→    let source = Arc::new(S3Storage::new(&cli.source_config())?);
199→
200→    let target = Arc::new(DuckDBSink::new(&cli.duckdb_path)?);
201→    let target_sink: Arc<dyn etl::sink::Sink> = Arc::clone(&target) as Arc<dyn etl::sink::Sink>;
202→
203→    let mutations = MutationConfig::new(0.0, 0.0);
204→
205→    let mut pipeline = ETLPipeline::new(
206→        dataset_source,
207→        &dataset_config,
208→        source,
209→        target_sink,
210→        &mutations,
211→    )?
212→    .with_created_at(cli.with_created_at);
213→
214→    tracing::info!(
215→        scenario = %scenario_name,
216→        dataset = %cli.dataset,
217→        bucket = %cli.bucket,
218→        source_prefix = %cli.source_prefix,
219→        duckdb_path = %cli.duckdb_path.display(),
220→        scale_factor = cli.scale_factor,
221→        num_steps = cli.num_steps,
222→        checkpoint_interval = cli.checkpoint_interval_steps,
223→        checkpoint_dir = %cli.checkpoint_dir.display(),
224→        "Starting Checkpointer"
225→    );
226→
227→    // Log the tables and schemas that will be processed.
228→    let datasets = pipeline.create_tables_request_datasets();
229→    for (name, config) in &datasets {
230→        tracing::info!(table = %name, schema = ?config.schema, "Dataset table registered");
231→    }
232→
233→    pipeline.initialize().await?;
234→    pipeline.run(cli.checkpoint_interval_steps as usize).await?;
235→
236→    let mut checkpoint_idx: usize = 0;
237→
238→    loop {
239→        let state = pipeline.wait().await;
240→
241→        match state {
242→            PipelineState::Paused => {
243→                // Pipeline paused after a batch of steps — take a checkpoint.
244→                tracing::info!(
245→                    checkpoint = checkpoint_idx,
246→                    "Pipeline paused, running checkpoint queries"
247→                );
248→                run_checkpoint_queries(
249→                    &target,
250→                    &checkpoint_queries,
251→                    &cli.checkpoint_dir,
252→                    checkpoint_idx,
253→                )
254→                .await?;
255→                checkpoint_idx += 1;
256→
257→                // Resume the pipeline for the next batch of steps.
258→                pipeline.continue_pipeline()?;
259→            }
260→            PipelineState::Stopped(StopReason::Completed) => {
261→                // Take a final checkpoint at completion.
262→                tracing::info!(
263→                    checkpoint = checkpoint_idx,
264→                    "Pipeline completed, running final checkpoint queries"
265→                );
266→                run_checkpoint_queries(
267→                    &target,
268→                    &checkpoint_queries,
269→                    &cli.checkpoint_dir,
270→                    checkpoint_idx,
271→                )
272→                .await?;
273→
274→                // Upload all checkpoints to S3.
275→                let checkpoint_store = CheckpointStore::new(
276→                    &cli.bucket,
277→                    &cli.source_prefix,
278→                    cli.region.as_deref(),
279→                    cli.endpoint.as_deref(),
280→                )?;
281→                checkpoint_store
282→                    .upload_checkpoints(
283→                        &scenario_name,
284→                        &cli.checkpoint_dir,
285→                        cli.checkpoint_interval_steps as usize,
286→                    )
287→                    .await?;
288→
289→                tracing::info!("Checkpointer completed successfully");
290→                break;
291→            }
292→            PipelineState::Stopped(StopReason::Cancelled) => {
293→                tracing::warn!("Checkpointer was cancelled");
294→                break;
295→            }
296→            PipelineState::Stopped(StopReason::Error(e)) => {
297→                tracing::error!(error = %e, "Checkpointer stopped with error");
298→                anyhow::bail!("Checkpointer failed: {e}");
299→            }
300→            other => {
301→                anyhow::bail!("Unexpected final pipeline state: {other:?}");
302→            }
303→        }
304→    }
305→
306→    Ok(())
307→}
