 17→//! Query execution abstraction for test framework
 18→//!
 19→//! This module provides a trait-based architecture for executing queries against different backends.
 20→//! It enables the test framework to work with both Spice databases and non-Spice databases through
 21→//! a common interface.
 22→//!
 23→//! # Architecture
 24→//!
 25→//! The core abstraction is the [`QueryExecutor`] trait, which defines a common interface for
 26→//! executing queries. Different executor implementations handle the specifics of communicating
 27→//! with their respective backends.
 28→//!
 29→//! # Built-in Executors
 30→//!
 31→//! ## [`FlightExecutor`]
 32→//! Executes queries via Arrow Flight SQL protocol.
 33→//! - **Use when**: Testing Spice with the default Flight SQL interface
 34→//! - **Supports validation**: Yes (returns full Arrow batches)
 35→//! - **Supports explain plans**: Yes (via `as_flight_client()`)
 36→//!
 37→//! ## [`HttpExecutor`]
 38→//! Executes queries via synchronous HTTP `/v1/sql` endpoint.
 39→//! - **Use when**: Testing Spice's HTTP API or measuring HTTP performance
 40→//! - **Supports validation**: No (only returns row counts)
 41→//! - **Supports explain plans**: No
 42→//!
 43→//! ## [`DistributedExecutor`]
 44→//! Executes queries via asynchronous HTTP `/v1/queries` API with polling.
 45→//! - **Use when**: Testing Spice in cluster mode with distributed query execution
 46→//! - **Supports validation**: No (only returns row counts)
 47→//! - **Supports explain plans**: No
 48→//!
 49→//! # Adding Support for New Databases
 50→//!
 51→//! To add support for a new database (e.g., `PostgreSQL`, `MySQL`), implement the [`QueryExecutor`] trait:
 52→//!
 53→//! ```rust,ignore
 54→//! use async_trait::async_trait;
 55→//! use std::sync::Arc;
 56→//!
 57→//! pub struct PostgresExecutor {
 58→//!     client: Arc<tokio_postgres::Client>,
 59→//! }
 60→//!
 61→//! #[async_trait]
 62→//! impl QueryExecutor for PostgresExecutor {
 63→//!     async fn execute(&self, query: &Query) -> Result<ExecutionResult> {
 64→//!         let start = std::time::Instant::now();
 65→//!         let rows = self.client.query(&query.sql, &[]).await?;
 66→//!
 67→//!         Ok(ExecutionResult {
 68→//!             duration: start.elapsed(),
 69→//!             row_count: rows.len(),
 70→//!             batches: None, // Or convert rows to Arrow batches for validation
 71→//!         })
 72→//!     }
 73→//!
 74→//!     fn name(&self) -> &str { "postgres" }
 75→//!     fn supports_validation(&self) -> bool { false }
 76→//!     fn clone_box(&self) -> Box<dyn QueryExecutor> { Box::new(self.clone()) }
 77→//! }
 78→//! ```
 79→//!
 80→//! Then use it in your test command:
 81→//!
 82→//! ```rust,ignore
 83→//! let executor: Box<dyn QueryExecutor> = Box::new(PostgresExecutor::new(client));
 84→//! let test_builder = NotStarted::new().with_query_executor(executor);
 85→//! ```
 86→
 87→use anyhow::Result;
 88→use arrow::array::RecordBatch;
 89→use async_trait::async_trait;
 90→use flight_client::FlightClient;
 91→use futures::TryStreamExt;
 92→use std::{sync::Arc, time::Duration};
 93→
 94→use crate::queries::Query;
 95→
 96→/// Result of executing a single query
 97→#[derive(Debug)]
 98→pub struct ExecutionResult {
 99→    /// Time taken to execute the query
100→    pub duration: Duration,
101→    /// Number of rows returned
102→    pub row_count: usize,
103→    /// Actual record batches (optional, for validation/snapshots)
104→    /// Some executors (like HTTP) may not provide this
105→    pub batches: Option<Vec<RecordBatch>>,
106→}
107→
108→/// Trait for executing queries against different backends
109→#[async_trait]
110→pub trait QueryExecutor: Send + Sync {
111→    /// Execute a query and return the result
112→    async fn execute(&self, query: &Query) -> Result<ExecutionResult>;
113→
114→    /// Name of this executor for logging/metrics
115→    fn name(&self) -> &'static str;
116→
117→    /// Whether this executor supports validation (returns batches)
118→    fn supports_validation(&self) -> bool {
119→        true
120→    }
121→
122→    /// Get the underlying `FlightClient` if this is a Flight executor
123→    /// Used for Flight-specific features like explain plan snapshots
124→    fn as_flight_client(&self) -> Option<Arc<FlightClient>> {
125→        None
126→    }
127→
128→    /// Clone this executor into a Box
129→    fn clone_box(&self) -> Box<dyn QueryExecutor>;
130→}
131→
132→// Implement Clone for Box<dyn QueryExecutor>
133→impl Clone for Box<dyn QueryExecutor> {
134→    fn clone(&self) -> Self {
135→        self.clone_box()
136→    }
137→}
