206→// ============================================================================
207→// HTTP SQL Executor
208→// ============================================================================
209→
210→/// HTTP SQL executor - executes queries via synchronous /v1/sql endpoint
211→pub struct HttpExecutor {
212→    client: reqwest::Client,
213→    base_url: String,
214→}
215→
216→impl HttpExecutor {
217→    #[must_use]
218→    pub fn new(client: reqwest::Client, base_url: String) -> Self {
219→        Self { client, base_url }
220→    }
221→}
222→
223→impl Clone for HttpExecutor {
224→    fn clone(&self) -> Self {
225→        Self {
226→            client: self.client.clone(),
227→            base_url: self.base_url.clone(),
228→        }
229→    }
230→}
231→
232→#[async_trait]
233→impl QueryExecutor for HttpExecutor {
234→    async fn execute(&self, query: &Query) -> Result<ExecutionResult> {
235→        let start = std::time::Instant::now();
236→        let sql_text = query.to_sql_with_inlined_params();
237→        let sql_url = format!("{}/v1/sql", self.base_url);
238→
239→        let response = self
240→            .client
241→            .post(&sql_url)
242→            .header("Accept", "application/vnd.spiceai.sql.v1+json")
243→            .body(sql_text.to_string())
244→            .send()
245→            .await?;
246→
247→        let status = response.status();
248→        let response_text = response.text().await?;
249→
250→        if !status.is_success() {
251→            anyhow::bail!("HTTP request failed: {status} - {response_text}");
252→        }
253→
254→        let duration = start.elapsed();
255→
256→        let response_json: serde_json::Value = serde_json::from_str(&response_text)?;
257→        let row_count = response_json
258→            .get("row_count")
259→            .and_then(serde_json::Value::as_u64)
260→            .ok_or_else(|| anyhow::anyhow!("No row_count in HTTP response"))?;
261→
262→        #[expect(clippy::cast_possible_truncation)]
263→        let row_count = row_count as usize;
264→
265→        Ok(ExecutionResult {
266→            duration,
267→            row_count,
268→            batches: None, // HTTP endpoint doesn't return full batches
269→        })
270→    }
271→
272→    fn name(&self) -> &'static str {
273→        "http"
274→    }
275→
276→    fn supports_validation(&self) -> bool {
277→        false
278→    }
279→
280→    fn clone_box(&self) -> Box<dyn QueryExecutor> {
281→        Box::new(self.clone())
282→    }
283→}
