285→// ============================================================================
286→// Distributed Query Executor
287→// ============================================================================
288→
289→/// Maximum interval between status polls for distributed queries (caps exponential backoff)
290→const MAX_POLL_INTERVAL: Duration = Duration::from_millis(5000);
291→/// Maximum time to wait for a distributed query to complete (1 hour)
292→const POLL_TIMEOUT: Duration = Duration::from_secs(3600);
293→
294→/// Distributed query executor - executes queries via async /v1/queries endpoint
295→pub struct DistributedExecutor {
296→    client: reqwest::Client,
297→    base_url: String,
298→}
299→
300→impl DistributedExecutor {
301→    #[must_use]
302→    pub fn new(client: reqwest::Client, base_url: String) -> Self {
303→        Self { client, base_url }
304→    }
305→}
306→
307→impl Clone for DistributedExecutor {
308→    fn clone(&self) -> Self {
309→        Self {
310→            client: self.client.clone(),
311→            base_url: self.base_url.clone(),
312→        }
313→    }
314→}
315→
316→#[async_trait]
317→impl QueryExecutor for DistributedExecutor {
318→    async fn execute(&self, query: &Query) -> Result<ExecutionResult> {
319→        let start = std::time::Instant::now();
320→        let sql_text = query.to_sql_with_inlined_params();
321→        let queries_url = format!("{}/v1/queries", self.base_url);
322→
323→        // Step 1: Submit the query
324→        let submit_body = serde_json::json!({
325→            "sql": sql_text,
326→        });
327→
328→        let submit_response = self
329→            .client
330→            .post(&queries_url)
331→            .header("Content-Type", "application/json")
332→            .json(&submit_body)
333→            .send()
334→            .await?;
335→
336→        let submit_status = submit_response.status();
337→        if !submit_status.is_success() {
338→            let error_text = submit_response.text().await.unwrap_or_default();
339→            anyhow::bail!("Query distributed submit failed: {submit_status} - {error_text}");
340→        }
341→
342→        let submit_json: serde_json::Value = submit_response.json().await?;
343→        let query_id = submit_json
344→            .get("query_id")
345→            .and_then(serde_json::Value::as_str)
346→            .ok_or_else(|| anyhow::anyhow!("No query_id in submit response"))?;
347→
348→        // Step 2: Poll for completion
349→        let status_url = format!("{queries_url}/{query_id}/status");
350→        let mut poll_interval = Duration::from_millis(100);
351→
352→        let poll_start = std::time::Instant::now();
353→        loop {
354→            if poll_start.elapsed() > POLL_TIMEOUT {
355→                anyhow::bail!("Query timed out waiting for distributed execution");
356→            }
357→
358→            let status_response = self.client.get(&status_url).send().await?;
359→
360→            if !status_response.status().is_success() {
361→                let error_text = status_response.text().await.unwrap_or_default();
362→                anyhow::bail!("Query status check failed: {error_text}");
363→            }
364→
365→            let status_json: serde_json::Value = status_response.json().await?;
366→            let state = status_json
367→                .get("state")
368→                .and_then(serde_json::Value::as_str)
369→                .unwrap_or("unknown");
370→
371→            match state {
372→                "succeeded" => break,
373→                "failed" => {
374→                    let error_msg = status_json
375→                        .get("error")
376→                        .and_then(|e| e.get("message"))
377→                        .and_then(serde_json::Value::as_str)
378→                        .unwrap_or("Unknown error");
379→                    anyhow::bail!("Query distributed execution failed: {error_msg}");
380→                }
381→                "cancelled" => anyhow::bail!("Query was cancelled"),
382→                "closed" => anyhow::bail!("Query results expired before retrieval"),
383→                "pending" | "running" => {
384→                    // Continue polling with exponential backoff
385→                    tokio::time::sleep(poll_interval).await;
386→                    poll_interval = std::cmp::min(poll_interval * 2, MAX_POLL_INTERVAL);
387→                }
388→                _ => {
389→                    // Unknown state, continue polling
390→                    tokio::time::sleep(poll_interval).await;
391→                    poll_interval = std::cmp::min(poll_interval * 2, MAX_POLL_INTERVAL);
392→                }
393→            }
394→        }
395→
396→        // Step 3: Fetch results (first chunk to get row count)
397→        let results_url = format!("{queries_url}/{query_id}/results");
398→        let results_response = self.client.get(&results_url).send().await?;
399→
400→        let results_status = results_response.status();
401→        if !results_status.is_success() {
402→            let error_text = results_response.text().await.unwrap_or_default();
403→            anyhow::bail!("Query results fetch failed: {results_status} - {error_text}");
404→        }
405→
406→        let results_json: serde_json::Value = results_response.json().await?;
407→
408→        // Get total row count from manifest
409→        let manifest = results_json
410→            .get("manifest")
411→            .ok_or_else(|| anyhow::anyhow!("Query results response missing 'manifest' field"))?;
412→
413→        let total_row_count_value = manifest.get("total_row_count").ok_or_else(|| {
414→            anyhow::anyhow!("Query results manifest missing 'total_row_count' field")
415→        })?;
416→
417→        let total_row_count_u64 = total_row_count_value.as_u64().ok_or_else(|| {
418→            anyhow::anyhow!("Query results manifest 'total_row_count' field is not a valid u64")
419→        })?;
420→
421→        #[expect(clippy::cast_possible_truncation)]
422→        let row_count = total_row_count_u64 as usize;
423→
424→        Ok(ExecutionResult {
425→            duration: start.elapsed(),
426→            row_count,
427→            batches: None, // Distributed mode doesn't return batches
428→        })
429→    }
430→
431→    fn name(&self) -> &'static str {
432→        "distributed"
433→    }
434→
435→    fn supports_validation(&self) -> bool {
436→        false
437→    }
438→
439→    fn clone_box(&self) -> Box<dyn QueryExecutor> {
440→        Box::new(self.clone())
441→    }
442→}
