 155→#[derive(Debug, Clone, PartialEq)]
 156→pub struct Query {
 157→    pub name: Arc<str>,
 158→    pub sql: Arc<str>,
 159→    pub overridden: bool,
 160→    pub parameters: Option<Vec<ParameterValue>>,
 161→}
 162→
 163→impl Query {
 164→    #[must_use]
 165→    pub fn new(name: Arc<str>, sql: Arc<str>, overridden: bool) -> Self {
 166→        Self {
 167→            name,
 168→            sql,
 169→            overridden,
 170→            parameters: None,
 171→        }
 172→    }
 173→
 174→    #[must_use]
 175→    pub fn get_parameters_batch(&self) -> Option<anyhow::Result<RecordBatch>> {
 176→        self.parameters.as_ref().map(|params| {
 177→            let columns: Vec<_> = params
 178→                .iter()
 179→                .enumerate()
 180→                .map(|(i, param)| {
 181→                    let name = format!("${}", i + 1);
 182→                    let dtype = param.dtype();
 183→                    let array = param.array();
 184→                    PreparedStatementParamColumn::new(name, dtype, false, array)
 185→                })
 186→                .collect();
 187→
 188→            create_param_batch(columns)
 189→        })
 190→    }
 191→
 192→    /// Converts parameterized SQL to raw SQL with parameters substituted as literals
 193→    /// for use with endpoints that don't support parameterized queries.
 194→    #[must_use]
 195→    pub fn to_sql_with_inlined_params(&self) -> Arc<str> {
 196→        match &self.parameters {
 197→            Some(params) if !params.is_empty() => {
 198→                let mut sql = self.sql.as_ref().to_string();
 199→
 200→                // Handle different parameter formats
 201→                if sql.contains('?') {
 202→                    // Positional format: replace ? with actual values
 203→                    for param in params {
 204→                        sql = sql.replacen('?', &param.to_sql_literal(), 1);
 205→                    }
 206→                } else {
 207→                    // Named format: replace $1, $2, etc. with actual values
 208→                    for (i, param) in params.iter().enumerate() {
 209→                        let placeholder = format!("${}", i + 1);
 210→                        sql = sql.replace(&placeholder, &param.to_sql_literal());
 211→                    }
 212→                }
 213→
 214→                sql.into()
 215→            }
 216→            _ => Arc::clone(&self.sql),
 217→        }
 218→    }
 219→
 220→    /// Rewrite table references in the query to use a reference schema.
 221→    /// This is used for validation against known good tables.
 222→    ///
 223→    /// For example, if `reference_schema` is \"arrow\", the query:
 224→    ///   `SELECT * FROM customer WHERE c_custkey = 1`
 225→    /// becomes:
 226→    ///   `SELECT * FROM arrow.customer WHERE c_custkey = 1`
 227→    ///
 228→    /// Uses `DataFusion`'s SQL parser to parse the query, rewrite all table references,
 229→    /// and unparse back to SQL. This works with any valid SQL query.
 230→    ///
 231→    /// # Errors
 232→    /// Returns an error if:
 233→    /// - The SQL query cannot be parsed
 234→    /// - The query contains multiple statements (only single statements are supported)
 235→    pub fn rewrite_with_reference_schema(&self, reference_schema: &str) -> anyhow::Result<Self> {
 236→        use datafusion::sql::sqlparser::ast::{Ident, ObjectNamePart, visit_relations_mut};
 237→        use datafusion::sql::sqlparser::parser::Parser;
 238→        use std::ops::ControlFlow;
 239→
 240→        // Parse the SQL query using sqlparser
 241→        let dialect = datafusion::sql::sqlparser::dialect::PostgreSqlDialect {};
 242→        let mut statements = Parser::parse_sql(&dialect, &self.sql).map_err(|e| {
 243→            anyhow::anyhow!(
 244→                "Failed to parse query '{}' for reference schema rewrite: {}",
 245→                self.name,
 246→                e
 247→            )
 248→        })?;
 249→
 250→        // Should have exactly one statement
 251→        if statements.len() != 1 {
 252→            anyhow::bail!(
 253→                "Query '{}' has {} SQL statements (expected 1) for reference schema rewrite",
 254→                self.name,
 255→                statements.len()
 256→            );
 257→        }
 258→
 259→        let statement = &mut statements[0];
 260→
 261→        // Visit and rewrite all table references in the statement
 262→        let _ = visit_relations_mut(statement, |table_name| {
 263→            // Only rewrite if the table doesn't already have a schema prefix (single-part name)
 264→            if table_name.0.len() == 1 {
 265→                // Prepend the reference schema to the table name
 266→                table_name
 267→                    .0
 268→                    .insert(0, ObjectNamePart::Identifier(Ident::new(reference_schema)));
 269→            }
 270→            ControlFlow::<()>::Continue(())
 271→        });
 272→
 273→        // Unparse the modified statement back to SQL
 274→        let rewritten_sql = statement.to_string();
 275→
 276→        Ok(Self {
 277→            name: Arc::clone(&self.name),
 278→            sql: Arc::from(rewritten_sql),
 279→            overridden: self.overridden,
 280→            parameters: self.parameters.clone(),
 281→        })
 282→    }
 283→}
