493→    pub fn build_extended_metrics<'a, M>(
494→        &self,
495→        metrics_iter: impl Iterator<Item = Option<&'a M>>,
496→    ) -> Result<BTreeMap<String, Builder>>
497→    where
498→        M: ExtendedMetrics + 'a,
499→    {
500→        let mut extended_metrics_builders = M::builders();
501→        for e in metrics_iter {
502→            if let Some(extended_metrics) = e {
503→                let extended_metrics = extended_metrics.build()?;
504→                for target in extended_metrics {
505→                    match target {
506→                        BuilderTarget::String((name, value)) => {
507→                            match extended_metrics_builders.get_mut(&name) {
508→                                Some(Builder::String(builder)) => builder.append_value(value),
509→                                Some(b) => {
510→                                    return Err(anyhow::anyhow!(
511→                                        "Invalid builder type for String: {b}"
512→                                    ));
513→                                }
514→                                None => {
515→                                    return Err(anyhow::anyhow!(
516→                                        "No builder found for String: {name}"
517→                                    ));
518→                                }
519→                            }
520→                        }
521→                        BuilderTarget::UInt64((name, value)) => {
522→                            match extended_metrics_builders.get_mut(&name) {
523→                                Some(Builder::UInt64(builder)) => builder.append_value(value),
524→                                Some(b) => {
525→                                    return Err(anyhow::anyhow!(
526→                                        "Invalid builder type for UInt64: {b}"
527→                                    ));
528→                                }
529→                                None => {
530→                                    return Err(anyhow::anyhow!(
531→                                        "No builder found for UInt64: {name}"
532→                                    ));
533→                                }
534→                            }
535→                        }
536→                        BuilderTarget::Float64((name, value)) => {
537→                            match extended_metrics_builders.get_mut(&name) {
538→                                Some(Builder::Float64(builder)) => builder.append_value(value),
539→                                Some(b) => {
540→                                    return Err(anyhow::anyhow!(
541→                                        "Invalid builder type for Float64: {b}"
542→                                    ));
543→                                }
544→                                None => {
545→                                    return Err(anyhow::anyhow!(
546→                                        "No builder found for Float64: {name}"
547→                                    ));
548→                                }
549→                            }
550→                        }
551→                    }
552→                }
553→            } else {
554→                for builder in &mut extended_metrics_builders.values_mut() {
555→                    match builder {
556→                        Builder::String(builder) => builder.append_null(),
557→                        Builder::UInt64(builder) => builder.append_null(),
558→                        Builder::Float64(builder) => builder.append_null(),
559→                    }
560→                }
561→            }
562→        }
563→
564→        Ok(extended_metrics_builders)
565→    }
566→
567→    /// Builds record batches for the individual metrics of this test run
568→    /// For example, a record would be a single query execution
569→    pub fn build_records(&self) -> Result<Vec<RecordBatch>> {
570→        let run_id = vec![self.run_id.to_string(); self.metrics.len()];
571→        let spiced_version = vec![self.spiced_version.clone(); self.metrics.len()];
572→
573→        let started_at = extract_metric_values!(self.metrics, started_at, as_u64);
574→        let finished_at = extract_metric_values!(self.metrics, finished_at, as_u64);
575→        let query_name = extract_metric_values!(self.metrics, query_name, clone);
576→        let query_status = extract_metric_values!(self.metrics, query_status, to_string);
577→        let min_duration_ms = extract_metric_values!(self.metrics, min_duration_ms);
578→        let max_duration_ms = extract_metric_values!(self.metrics, max_duration_ms);
579→        let iterations = extract_metric_values!(self.metrics, iterations, as_u64);
580→        let median_duration_ms = extract_metric_values!(self.metrics, median_duration_ms);
581→        let percentile_99_duration_ms =
582→            extract_metric_values!(self.metrics, percentile_99_duration_ms);
583→        let percentile_95_duration_ms =
584→            extract_metric_values!(self.metrics, percentile_95_duration_ms);
585→        let percentile_90_duration_ms =
586→            extract_metric_values!(self.metrics, percentile_90_duration_ms);
587→
588→        let commit_sha = vec![self.commit_sha.clone(); self.metrics.len()];
589→        let branch_name = vec![self.branch_name.clone(); self.metrics.len()];
590→
591→        let mut columns: Vec<ArrayRef> = vec![
592→            Arc::new(StringArray::from(run_id)),
593→            Arc::new(StringArray::from(spiced_version)),
594→            Arc::new(UInt64Array::from(started_at)),
595→            Arc::new(UInt64Array::from(finished_at)),
596→            Arc::new(StringArray::from(
597→                query_name
598→                    .iter()
599→                    .map(ToString::to_string)
600→                    .collect::<Vec<_>>(),
601→            )),
602→            Arc::new(StringArray::from(query_status)),
603→            Arc::new(UInt64Array::from(min_duration_ms)),
604→            Arc::new(UInt64Array::from(max_duration_ms)),
605→            Arc::new(UInt64Array::from(iterations)),
606→            Arc::new(StringArray::from(commit_sha)),
607→            Arc::new(StringArray::from(branch_name)),
608→            Arc::new(UInt64Array::from(median_duration_ms)),
609→            Arc::new(UInt64Array::from(percentile_99_duration_ms)),
610→            Arc::new(UInt64Array::from(percentile_95_duration_ms)),
611→            Arc::new(UInt64Array::from(percentile_90_duration_ms)),
612→        ];
613→
614→        let extended_metrics_fields = T::fields();
615→        let extended_metrics_field_names = extended_metrics_fields
616→            .iter()
617→            .map(arrow::datatypes::Field::name)
618→            .collect::<Vec<_>>();
619→
620→        if !extended_metrics_fields.is_empty() {
621→            let mut extended_metrics_builders = self
622→                .build_extended_metrics(self.metrics.iter().map(|m| m.extended_metrics.as_ref()))?;
623→
624→            for field in extended_metrics_field_names {
625→                match extended_metrics_builders.get_mut(field) {
626→                    Some(Builder::String(builder)) => columns.push(Arc::new(builder.finish())),
627→                    Some(Builder::UInt64(builder)) => columns.push(Arc::new(builder.finish())),
628→                    Some(Builder::Float64(builder)) => columns.push(Arc::new(builder.finish())),
629→                    None => {
630→                        return Err(anyhow::anyhow!(
631→                            "No builder found for extended metric field: {field}"
632→                        ));
633→                    }
634→                }
635→            }
636→        }
637→
638→        Ok(vec![RecordBatch::try_new(Self::records_schema(), columns)?])
639→    }
