 48→/// The global meter for benchmark telemetry.
 49→///
 50→/// Initialized explicitly by [`Telemetry::new_with_resource()`] or
 51→/// [`Telemetry::with_otlp_resource()`] after the provider is set.
 52→/// Using `OnceLock` prevents the ordering issue where early access
 53→/// with `LazyLock` would permanently lock the meter to a noop provider.
 54→///
 55→/// When metrics are disabled and `METER` is never initialized, all
 56→/// metric operations fall through to noop via the `meter()` helper.
 57→pub static METER: OnceLock<Meter> = OnceLock::new();
 58→
 59→/// Shared noop meter used when `METER` has not been initialized.
 60→/// This avoids allocating a new `NoopMeterProvider` on every `meter()` call.
 61→static NOOP_METER: LazyLock<Meter> =
 62→    LazyLock::new(|| NoopMeterProvider::new().meter("benchmarks_telemetry"));
 63→
 64→/// Returns the initialized meter, or a shared noop meter if not yet initialized.
 65→#[must_use]
 66→pub fn meter() -> Meter {
 67→    METER.get().cloned().unwrap_or_else(|| NOOP_METER.clone())
 68→}
