223→impl SpiceTest<NotStarted> {
224→    fn get_new_progress_bar(&self) -> ProgressBar {
225→        match self.state.end_condition {
226→            EndCondition::Duration(duration) => {
227→                // refresh the progress bar every 10 seconds, or every 1/1000th of the duration
228→                // for an 8 hour test, this would be every ~28 seconds
229→                ProgressBar::new((duration.as_secs() / self.state.query_set.len() as u64) * 2)
230→                // this isn't 100% representative of the progress bar count, but it's close enough (2s per query)
231→            }
232→            EndCondition::QuerySetCompleted(count) => {
233→                ProgressBar::new((self.state.query_set.len() * count) as u64)
234→            }
235→            EndCondition::Unlimited => {
236→                // For unlimited tests, use a spinner-style progress bar
237→                ProgressBar::new_spinner()
238→            }
239→        }
240→    }
241→
242→    pub fn start(mut self) -> Result<SpiceTest<Running>> {
243→        if self.state.query_set.is_empty() {
244→            return Err(anyhow::anyhow!("Query set is empty"));
245→        }
246→
247→        if self.state.parallel_count == 0 {
248→            return Err(anyhow::anyhow!("Parallel count must be greater than 0"));
249→        }
250→
251→        // Ensure executor is configured
252→        let executor = self
253→            .state
254→            .query_executor
255→            .take()
256→            .ok_or_else(|| anyhow::anyhow!("Query executor not configured"))?;
257→
258→        let multi = if self.use_progress_bars {
259→            Some(MultiProgress::new())
260→        } else {
261→            None
262→        };
263→
264→        let shutdown_token = tokio_util::sync::CancellationToken::new();
265→
266→        let row_count_validation_skip_queries: Vec<String> = self
267→            .state
268→            .query_set_type
269→            .as_ref()
270→            .map(|qs| {
271→                qs.get_row_count_validation_skip_queries(
272→                    self.state.query_overrides,
273→                    self.state.scale_factor,
274→                )
275→                .into_iter()
276→                .map(String::from)
277→                .collect()
278→            })
279→            .unwrap_or_default();
280→
281→        let mut query_workers = Vec::new();
282→        for id in 0..self.state.parallel_count {
283→            let mut worker = SpiceTestQueryWorker::new(
284→                id,
285→                self.state.query_set.clone(),
286→                self.state.end_condition,
287→                self.name.clone(),
288→                executor.clone(),
289→            )
290→            .with_explain_plan_snapshot(self.explain_plan_snapshot)
291→            .with_results_snapshot(self.results_snapshot_predicate)
292→            .with_validate(self.state.validate)
293→            .with_scale_factor(self.state.scale_factor)
294→            .with_shutdown_token(shutdown_token.clone())
295→            .with_skip_row_count_validation(row_count_validation_skip_queries.clone());
296→
297→            if let Some(multi) = &multi {
298→                worker = worker.with_progress_bar(multi.add(self.get_new_progress_bar()));
299→            }
300→
301→            if let Some(validation_data) = &self.state.validation_data {
302→                worker = worker.with_validation_data(validation_data.clone());
303→            }
304→
305→            if let Some(reference_schema) = &self.state.reference_schema {
306→                worker = worker.with_reference_schema(Some(reference_schema.clone()));
307→            }
308→
309→            if let Some(sender) = &self.state.streaming_metrics_sender {
310→                worker = worker.with_streaming_metrics(sender.clone());
311→            }
312→
313→            if let Some(threshold) = self.state.query_duration_threshold {
314→                worker = worker.with_query_duration_threshold(threshold);
315→            }
316→
317→            query_workers.push(worker.start());
318→        }
319→
320→        Ok(SpiceTest {
321→            name: self.name,
322→            spiced_instance: self.spiced_instance,
323→            start_time: self.start_time,
324→            use_progress_bars: self.use_progress_bars,
325→            api_key: self.api_key,
326→            explain_plan_snapshot: self.explain_plan_snapshot,
327→            results_snapshot_predicate: self.results_snapshot_predicate,
328→            state: Running {
329→                start_time: Instant::now(),
330→                query_workers,
331→                progress_bar: multi,
332→                query_count: self.state.query_count,
333→                parallel_count: self.state.parallel_count,
334→                end_condition: self.state.end_condition,
335→                shutdown_token,
336→            },
337→        })
338→    }
339→}
340→
341→impl SpiceTest<Running> {
342→    #[must_use]
343→    pub fn cancellation_token(&self) -> tokio_util::sync::CancellationToken {
344→        self.state.shutdown_token.clone()
345→    }
346→
347→    pub fn cancel(&self) {
348→        self.state.shutdown_token.cancel();
349→    }
350→
351→    pub async fn wait(self) -> Result<SpiceTest<Completed>> {
352→        let mut query_durations = BTreeMap::new();
353→        let mut query_iteration_durations = BTreeMap::new();
354→        let mut row_counts = BTreeMap::new();
355→        let mut query_statuses = BTreeMap::new();
356→        for worker_result in join_all(self.state.query_workers).await {
357→            let worker_result = worker_result??;
358→            if worker_result.connection_failed {
359→                return Err(anyhow::anyhow!(
360→                    "Test failed - a connection failed during the test"
361→                ));
362→            }
363→
364→            for (query, duration) in worker_result.query_durations {
365→                query_durations
366→                    .entry(query)
367→                    .or_insert_with(Vec::new)
368→                    .extend(duration);
369→            }
370→
371→            for (query, iteration_durations) in worker_result.query_iteration_durations {
372→                query_iteration_durations
373→                    .entry(query)
374→                    .or_insert_with(|| iteration_durations);
375→            }
376→
377→            for (query, query_row_counts) in worker_result.row_counts {
378→                row_counts
379→                    .entry(query)
380→                    .or_insert_with(Vec::new)
381→                    .extend(query_row_counts);
382→            }
383→
384→            for (query, worker_status) in worker_result.query_statuses {
385→                query_statuses
386→                    .entry(query)
387→                    .and_modify(|existing_status| {
388→                        // If the worker reports failure, update the status to Failed
389→                        if matches!(existing_status, QueryStatus::Failed(_)) {
390→                            return; // don't update any existing status message
391→                        }
392→
393→                        if matches!(worker_status, QueryStatus::Failed(_)) {
394→                            *existing_status = worker_status.clone();
395→                        }
396→                    })
397→                    .or_insert(worker_status);
398→            }
399→        }
400→
401→        if let Some(multi) = self.state.progress_bar {
402→            multi.clear()?;
403→        }
404→
405→        Ok(SpiceTest {
406→            name: self.name,
407→            spiced_instance: self.spiced_instance,
408→            start_time: self.start_time,
409→            use_progress_bars: self.use_progress_bars,
410→            api_key: self.api_key,
411→            explain_plan_snapshot: self.explain_plan_snapshot,
412→            results_snapshot_predicate: self.results_snapshot_predicate,
413→            state: Completed {
414→                query_durations,
415→                query_iteration_durations,
416→                row_counts,
417→                query_statuses,
418→                test_duration: self.state.start_time.elapsed(),
419→                end_time: SystemTime::now(),
420→                query_count: self.state.query_count,
421→                parallel_count: self.state.parallel_count,
422→                end_condition: self.state.end_condition,
423→            },
424→        })
425→    }
426→}
427→
428→impl SpiceTest<Completed> {
429→    #[must_use]
430→    pub fn get_query_durations(&self) -> &BTreeMap<Arc<str>, Vec<Duration>> {
431→        &self.state.query_durations
432→    }
433→
434→    /// Returns the start and end time of for all consecutive query iterations of the same query in a set.
435→    ///
436→    /// Only valid when the `EndCondition` is `QuerySetCompleted`.
437→    #[must_use]
438→    pub fn get_query_iteration_durations(&self) -> &BTreeMap<Arc<str>, (SystemTime, SystemTime)> {
439→        &self.state.query_iteration_durations
440→    }
441→
442→    #[must_use]
443→    pub fn get_cumulative_query_duration(&self) -> Duration {
444→        self.state.query_durations.values().flatten().copied().sum()
445→    }
446→
447→    #[must_use]
448→    pub fn get_test_duration(&self) -> Duration {
449→        self.state.test_duration
450→    }
451→
452→    pub fn get_throughput_metric(&self, scale: f64) -> Result<f64> {
453→        // metric = (Parallel Query Count * Test Suite Query Count * 3600) / Cs * Scale
454→        let lhs = self.state.parallel_count * self.state.query_count * 3600;
455→
456→        // u32 is safe because lhs is unlikely to be greater than u32::MAX unless some extreme parameters are used (more than 1000 parallel and query count)
457→        let lhs = f64::from(u32::try_from(lhs)?);
458→
459→        // because we perform query sets one after the other, we're not 100% like the original TPCH QpH metric because it expects to only run once
460→        // apply a modifier based on the query set count
461→        // e.g. query set count of 5, means our calculated QpH needs to be times 5 because we ran 5 query sets
462→        // this adjusts for a longer test duration as a result of running multiple query sets, which would otherwise reduce the QpH
463→        let end_condition_modifier = match self.state.end_condition {
464→            EndCondition::Duration(_) => {
465→                return Err(anyhow::anyhow!(
466→                    "Throughput metric calculation for duration-based tests is not supported. Use a QuerySetCompleted test instead."
467→                ));
468→            }
469→            EndCondition::Unlimited => {
470→                return Err(anyhow::anyhow!(
471→                    "Throughput metric calculation is not supported for unlimited tests."
472→                ));
473→            }
474→            EndCondition::QuerySetCompleted(count) => f64::from(u32::try_from(count)?),
475→        };
476→
477→        Ok((lhs / self.state.test_duration.as_secs_f64()) * scale * end_condition_modifier)
478→    }
479→
480→    /// Validates that row counts are consistent across queries
481→    /// Each query should return the same number of rows
482→    pub fn validate_returned_row_counts(&self) -> Result<BTreeMap<Arc<str>, usize>> {
483→        // validate that row counts are consistent across queries - each query should return the same number of rows
484→        let mut returned_row_counts = BTreeMap::new();
485→        for (query, counts) in &self.state.row_counts {
486→            let first = counts
487→                .first()
488→                .ok_or_else(|| anyhow::anyhow!("No row counts found for query {query}"))?;
489→            if !counts.iter().all(|count| count == first) {
490→                return Err(anyhow::anyhow!(
491→                    "Row counts for query {query} are inconsistent"
492→                ));
493→            }
494→
495→            returned_row_counts.insert(Arc::clone(query), *first);
496→        }
497→
498→        Ok(returned_row_counts)
499→    }
500→
501→    /// Returns true if every query status is passed. Returns false if any query status is failed.
502→    #[must_use]
503→    pub fn succeeded(&self) -> bool {
504→        self.state
505→            .query_statuses
506→            .values()
507→            .all(|status| status == &QueryStatus::Passed)
508→    }
509→}
510→
511→impl std::fmt::Display for SpiceTest<Completed> {
512→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
513→        write!(
514→            f,
515→            "SpiceTest: {} - Cumulative query duration: {} seconds, Test duration: {} seconds",
516→            self.name,
517→            self.get_cumulative_query_duration().as_secs_f32(),
518→            self.get_test_duration().as_secs_f32()
519→        )
520→    }
521→}
