139→    /// Create an instance that connects to an external spiced at the given Flight URL.
140→    ///
141→    /// The HTTP base URL is derived from the Flight URL by replacing the port with 8090,
142→    /// or can be explicitly provided.
143→    #[must_use]
144→    pub fn external(flight_url: impl Into<String>) -> Self {
145→        let flight_url = flight_url.into();
146→        // Derive HTTP URL from Flight URL by replacing port
147→        // e.g., "http://localhost:50051" -> "http://localhost:8090"
148→        let http_base_url = if let Some(last_colon) = flight_url.rfind(':') {
149→            format!("{}:8090", &flight_url[..last_colon])
150→        } else {
151→            format!("{flight_url}:8090")
152→        };
153→        Self::External {
154→            flight_url,
155→            http_base_url,
156→        }
157→    }
158→
159→    /// Create an instance with explicit Flight and HTTP URLs.
160→    #[must_use]
161→    pub fn external_with_http(
162→        flight_url: impl Into<String>,
163→        http_base_url: impl Into<String>,
164→    ) -> Self {
165→        Self::External {
166→            flight_url: flight_url.into(),
167→            http_base_url: http_base_url.into(),
168→        }
169→    }
170→
171→    /// Start a spiced instance
172→    ///
173→    /// # Errors
174→    ///
175→    /// - If spiced is already running
176→    /// - If the spiced instance fails to start
177→    /// - If the spicepod definition fails to serialize
178→    pub async fn start(mut start_request: StartRequest) -> Result<Self> {
179→        // Check if spiced is already running
180→        let client = reqwest::Client::new();
181→        let health_url = format!("{HTTP_BASE_URL}{HEALTH_ENDPOINT}");
182→        let response = client.get(&health_url).send().await;
183→        if response.is_ok() {
184→            anyhow::bail!("Spiced instance is already running");
185→        }
186→
187→        if !start_request.prepared {
188→            start_request.prepare()?;
189→        }
190→
191→        let tempdir = start_request.tempdir;
192→
193→        // Get spiced version
194→        let version_cmd = Command::new(start_request.spiced_path.clone())
195→            .arg("--version")
196→            .output()?;
197→
198→        if !version_cmd.status.success() {
199→            anyhow::bail!(
200→                "Failed to get spiced version: {}",
201→                String::from_utf8_lossy(&version_cmd.stderr)
202→            );
203→        }
204→
205→        let version = String::from_utf8_lossy(&version_cmd.stdout).to_string();
206→        // take just the v1.0.0 part of the version
207→        let version = match (version.contains('-'), version.contains('+')) {
208→            (true, _) => version.split('-').next().unwrap_or(&version).to_string(),
209→            (false, true) => version.split('+').next().unwrap_or(&version).to_string(),
210→            (false, false) => version,
211→        };
212→
213→        // Start the spiced instance
214→        let mut cmd = Command::new(start_request.spiced_path);
215→        cmd.current_dir(tempdir.path());
216→        cmd.arg("--telemetry-enabled=false");
217→
218→        // Add any additional arguments
219→        for arg in start_request.additional_args {
220→            cmd.arg(arg);
221→        }
222→
223→        let child = cmd.spawn()?;
224→
225→        Ok(Self::Owned {
226→            child,
227→            tempdir,
228→            version: SpicedVersion::new(version),
229→        })
230→    }
231→
232→    #[must_use]
233→    pub fn version(&self) -> &str {
234→        let Self::Owned { version, .. } = self else {
235→            return "unknown";
236→        };
237→
238→        version.0.as_str()
239→    }
