241→    pub fn get_tempdir_path(&self) -> Result<PathBuf> {
242→        let Self::Owned { tempdir, .. } = self else {
243→            anyhow::bail!("SpicedInstance is not owned, no tempdir available");
244→        };
245→
246→        Ok(tempdir.path().to_path_buf())
247→    }
248→
249→    /// Get a flight client for the spiced instance
250→    ///
251→    /// # Errors
252→    ///
253→    /// - If the flight client fails to be created
254→    pub async fn flight_client(
255→        &self,
256→        api_key: Option<String>,
257→        disable_caching: bool,
258→    ) -> Result<FlightClient> {
259→        let credentials = if let Some(key) = api_key {
260→            Credentials::Bearer {
261→                token: std::sync::Arc::new(SecretString::new(key.into())),
262→                prefix: true,
263→            }
264→        } else {
265→            Credentials::Anonymous
266→        };
267→
268→        let flight_url = match self {
269→            Self::External { flight_url, .. } => flight_url.as_str(),
270→            Self::Existing | Self::Owned { .. } => FLIGHT_URL,
271→        };
272→
273→        let mut metadata = tonic::metadata::MetadataMap::new();
274→        if disable_caching {
275→            metadata.insert("cache-control", "no-cache".parse()?);
276→        }
277→
278→        let flight_client = FlightClient::try_new(
279→            std::sync::Arc::from(flight_url),
280→            credentials,
281→            Some(metadata),
282→            None,
283→        )
284→        .await
285→        .map_err(|e| anyhow!("{e}"))?;
286→
287→        Ok(flight_client)
288→    }
289→
290→    /// Get an http client for the spiced instance
291→    ///
292→    /// # Errors
293→    ///
294→    /// - If the http client fails to be created
295→    pub fn http_client(&self) -> Result<reqwest::Client> {
296→        Ok(reqwest::Client::builder()
297→            .user_agent("spice-test-framework/1.0")
298→            .build()?)
299→    }
300→
301→    /// Get the HTTP base URL for this instance
302→    #[must_use]
303→    pub fn http_base_url(&self) -> &str {
304→        match self {
305→            Self::External { http_base_url, .. } => http_base_url.as_str(),
306→            Self::Existing | Self::Owned { .. } => HTTP_BASE_URL,
307→        }
308→    }
309→
310→    /// Wait for the spiced instance to be ready
311→    ///
312→    /// # Errors
313→    ///
314→    /// - If the spiced instance fails to be ready within the timeout
315→    pub async fn wait_for_ready(&mut self, timeout: Duration) -> Result<()> {
316→        // Wait for the spiced instance to be ready by polling the `/v1/ready` endpoint
317→        let client = self.http_client()?;
318→        let http_base = self.http_base_url().to_string();
319→        let ready_url = format!("{http_base}{READY_ENDPOINT}");
320→        if !wait_until_true(timeout, || async {
321→            let response = client.get(&ready_url).send().await;
322→            match response {
323→                Ok(response) => response.status().is_success(),
324→                Err(_) => false,
325→            }
326→        })
327→        .await
328→        {
329→            anyhow::bail!("Spiced instance not ready within {timeout:?}");
330→        }
331→
332→        // Give Flight server a moment to finish starting up after HTTP is ready
333→        // Flight starts asynchronously and may not be available immediately
334→        tokio::time::sleep(Duration::from_millis(500)).await;
335→
336→        Ok(())
337→    }
338→
339→    pub async fn is_ready(&self) -> bool {
340→        let Ok(client) = self.http_client() else {
341→            return false;
342→        };
343→        let ready_url = format!("{}{READY_ENDPOINT}", self.http_base_url());
344→        let response = client.get(&ready_url).send().await;
345→        match response {
346→            Ok(response) => response.status().is_success(),
347→            Err(_) => false,
348→        }
349→    }
350→
351→    /// Stop the spiced instance
352→    ///
353→    /// # Errors
354→    ///
355→    /// - If the spiced instance fails to exit
356→    pub fn stop(&mut self) -> Result<()> {
357→        let Self::Owned { child, .. } = self else {
358→            return Ok(());
359→        };
360→
361→        #[cfg(not(target_os = "windows"))]
362→        {
363→            // Send a SIGTERM to the spiced instance and wait for it to exit
364→            let Ok(pid_i32) = child.id().try_into() else {
365→                anyhow::bail!("Failed to convert pid to i32");
366→            };
367→            nix::sys::signal::kill(
368→                nix::unistd::Pid::from_raw(pid_i32),
369→                nix::sys::signal::Signal::SIGTERM,
370→            )?;
371→            child.wait()?;
372→        }
373→
374→        #[cfg(target_os = "windows")]
375→        {
376→            // On Windows, we can use the built-in process termination
377→            child.kill()?;
378→            child.wait()?;
379→        }
380→
381→        Ok(())
382→    }
383→
384→    /// Returns an instance of a `Process` for the spiced instance
385→    /// This allows tracking the spiced process, without owning the spiced instance
386→    pub fn process(&self) -> Result<Process> {
387→        let Self::Owned { child, .. } = self else {
388→            anyhow::bail!("SpicedInstance is not owned, no process available");
389→        };
390→
391→        Ok(Process::new(Pid::from_u32(child.id())))
392→    }
393→}
394→
395→impl Drop for SpicedInstance {
396→    fn drop(&mut self) {
397→        let Self::Owned { child, .. } = self else {
398→            return;
399→        };
400→
401→        match child.kill() {
402→            Ok(()) => (),
403→            Err(e) => eprintln!("Failed to kill spiced instance: {e}"),
404→        }
405→    }
406→}
