        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            if entry.file_type()?.is_file() {
                total_size += usize::try_from(entry.metadata()?.len())?;
            } else if entry.file_type()?.is_dir() {
                total_size += recursively_get_dir_size(&entry.path())?;
            }
        }
    }
    Ok(total_size)
}

