139→// ============================================================================
140→// Flight SQL Executor
141→// ============================================================================
142→
143→/// Flight SQL executor - executes queries via Arrow Flight SQL protocol
144→pub struct FlightExecutor {
145→    client: Arc<FlightClient>,
146→}
147→
148→impl FlightExecutor {
149→    #[must_use]
150→    pub fn new(client: Arc<FlightClient>) -> Self {
151→        Self { client }
152→    }
153→}
154→
155→impl Clone for FlightExecutor {
156→    fn clone(&self) -> Self {
157→        Self {
158→            client: Arc::clone(&self.client),
159→        }
160→    }
161→}
162→
163→#[async_trait]
164→impl QueryExecutor for FlightExecutor {
165→    async fn execute(&self, query: &Query) -> Result<ExecutionResult> {
166→        let start = std::time::Instant::now();
167→
168→        let mut result_stream = self
169→            .client
170→            .query(query.to_sql_with_inlined_params().as_ref())
171→            .await?;
172→
173→        let mut batches = Vec::new();
174→        let mut row_count = 0;
175→
176→        while let Some(batch) = result_stream.try_next().await? {
177→            let batch_rows = batch.num_rows();
178→            row_count += batch_rows;
179→            batches.push(batch);
180→        }
181→
182→        Ok(ExecutionResult {
183→            duration: start.elapsed(),
184→            row_count,
185→            batches: Some(batches),
186→        })
187→    }
188→
189→    fn name(&self) -> &'static str {
190→        "flight"
191→    }
192→
193→    fn supports_validation(&self) -> bool {
194→        true
195→    }
196→
197→    fn as_flight_client(&self) -> Option<Arc<FlightClient>> {
198→        Some(Arc::clone(&self.client))
199→    }
200→
201→    fn clone_box(&self) -> Box<dyn QueryExecutor> {
202→        Box::new(self.clone())
203→    }
204→}
