145→pub trait StatisticsCollector<T, C> {
146→    fn percentile(&self, percentile: f64) -> Result<T>;
147→    fn median(&self) -> Result<T>;
148→    fn statistical_set(&self) -> Result<C>;
149→    fn min_duration(&self) -> Result<T>;
150→    fn max_duration(&self) -> Result<T>;
151→}
152→
153→impl StatisticsCollector<Duration, Vec<Duration>> for Vec<Duration> {
154→    fn percentile(&self, percentile: f64) -> Result<Duration> {
155→        let mut sorted_durations = self.clone();
156→        sorted_durations.sort();
157→
158→        // safety: sorted_durations.len() cannot be negative, and is unlikely to be larger than u32::MAX
159→        #[expect(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
160→        {
161→            let rank =
162→                (percentile / 100.0) * (f64::from(u32::try_from(sorted_durations.len() - 1)?));
163→            if (rank - rank.floor()).abs() < FLOAT_ERROR_MARGIN {
164→                Ok(sorted_durations[rank as usize])
165→            } else {
166→                let lower_duration = sorted_durations[rank.floor() as usize];
167→                let upper_duration = sorted_durations[rank.ceil() as usize];
168→                Ok((lower_duration + upper_duration) / 2)
169→            }
170→        }
171→    }
172→
173→    fn median(&self) -> Result<Duration> {
174→        let mut sorted_durations = self.clone();
175→        sorted_durations.sort();
176→
177→        let half = sorted_durations.len() / 2;
178→        if sorted_durations.len().is_multiple_of(2) {
179→            Ok((sorted_durations[half - 1] + sorted_durations[half]) / 2)
180→        } else {
181→            Ok(sorted_durations[half])
182→        }
183→    }
184→
185→    fn min_duration(&self) -> Result<Duration> {
186→        self.iter()
187→            .min()
188→            .ok_or_else(|| anyhow::anyhow!("Cannot get min of empty duration list"))
189→            .copied()
190→    }
191→
192→    fn max_duration(&self) -> Result<Duration> {
193→        self.iter()
194→            .max()
195→            .ok_or_else(|| anyhow::anyhow!("Cannot get max of empty duration list"))
196→            .copied()
197→    }
198→
199→    fn statistical_set(&self) -> Result<Vec<Duration>> {
200→        if self.is_empty() {
201→            return Ok(vec![]);
202→        }
203→
204→        let mut sorted_durations = self.clone();
205→        sorted_durations.sort();
206→
207→        // calculate the inter-quartile range to remove statistical outliers
208→        // safety: sorted_durations.len() cannot be negative, and is unlikely to be larger than u32::MAX
209→        {
210→            let first_quartile_secs = sorted_durations.percentile(25.0)?.as_secs_f64();
211→            let third_quartile_secs = sorted_durations.percentile(75.0)?.as_secs_f64();
212→
213→            let iqr = third_quartile_secs - first_quartile_secs;
214→            let lower_bound = first_quartile_secs - 1.5 * iqr;
215→            let upper_bound = third_quartile_secs + 1.5 * iqr;
216→
217→            sorted_durations.retain(|duration| {
218→                let duration_secs = duration.as_secs_f64();
219→                duration_secs >= lower_bound && duration_secs <= upper_bound
220→            });
221→        }
222→
223→        Ok(if sorted_durations.is_empty() {
224→            self.clone() // if everything is an outlier, nothing is an outlier - keep everything
225→        } else {
226→            sorted_durations
227→        })
228→    }
229→}
