369→// Macro to help extract values from metric vecs
370→macro_rules! extract_metric_values {
371→    // no clone or to_string, direct copy
372→    ($metrics:expr, $field:ident) => {
373→        $metrics
374→            .iter()
375→            .map(|metric| metric.$field)
376→            .collect::<Vec<_>>()
377→    };
378→
379→    // clone
380→    ($metrics:expr, $field:ident, clone) => {
381→        $metrics
382→            .iter()
383→            .map(|metric| metric.$field.clone())
384→            .collect::<Vec<_>>()
385→    };
386→
387→    // to_string
388→    ($metrics:expr, $field:ident, to_string) => {
389→        $metrics
390→            .iter()
391→            .map(|metric| metric.$field.to_string())
392→            .collect::<Vec<_>>()
393→    };
394→
395→    // as u64
396→    ($metrics:expr, $field:ident, as_u64) => {
397→        $metrics
398→            .iter()
399→            .map(|metric| metric.$field as u64)
400→            .collect::<Vec<_>>()
401→    };
402→
403→    // as u32
404→    ($metrics:expr, $field:ident, as_u32) => {
405→        $metrics
406→            .iter()
407→            .map(|metric| metric.$field as u64)
408→            .collect::<Vec<_>>()
409→    };
410→
411→    // as i64
412→    ($metrics:expr, $field:ident, as_i64) => {
413→        $metrics
414→            .iter()
415→            .map(|metric| metric.$field as i64)
416→            .collect::<Vec<_>>()
417→    };
418→
419→    // as i32
420→    ($metrics:expr, $field:ident, as_i32) => {
421→        $metrics
422→            .iter()
423→            .map(|metric| to_i32(metric.$field))
424→            .collect::<Vec<_>>()
425→    };
426→}
