641→    /// Builds record batches for the test run
642→    /// The record batch is a single row, representing the run as a whole - which can pass or fail separately from individual queries
643→    pub fn build_run(&self, status: &QueryStatus) -> Result<Vec<RecordBatch>> {
644→        let run_id = vec![self.run_id.to_string()];
645→        let spiced_version = vec![self.spiced_version.clone()];
646→        let run_name = vec![self.run_name.clone()];
647→        let commit_sha = vec![self.commit_sha.clone()];
648→        let branch_name = vec![self.branch_name.clone()];
649→        let test_type = vec![self.test_type.to_string()];
650→        let started_at = vec![self.started_at as u64];
651→        let finished_at = vec![self.finished_at as u64];
652→        // the test can only pass if all queries pass, and the input status is a pass
653→        let status = [
654→            if self
655→                .metrics
656→                .iter()
657→                .all(|m| m.query_status == QueryStatus::Passed)
658→                && status.clone() == QueryStatus::Passed
659→            {
660→                QueryStatus::Passed
661→            } else {
662→                QueryStatus::Failed(None)
663→            },
664→        ];
665→
666→        let query_execution_count =
667→            vec![self.metrics.iter().fold(0, |acc, m| acc + m.iterations) as u64];
668→
669→        let memory_usage = vec![self.memory_usage];
670→
671→        let extended_metrics_fields = R::fields();
672→        let extended_metrics_field_names = extended_metrics_fields
673→            .iter()
674→            .map(arrow::datatypes::Field::name)
675→            .collect::<Vec<_>>();
676→
677→        let mut columns: Vec<ArrayRef> = vec![
678→            Arc::new(StringArray::from(run_id)),
679→            Arc::new(StringArray::from(spiced_version)),
680→            Arc::new(StringArray::from(run_name)),
681→            Arc::new(StringArray::from(commit_sha)),
682→            Arc::new(StringArray::from(branch_name)),
683→            Arc::new(StringArray::from(test_type)),
684→            Arc::new(UInt64Array::from(started_at)),
685→            Arc::new(UInt64Array::from(finished_at)),
686→            Arc::new(StringArray::from(
687→                status
688→                    .iter()
689→                    .map(std::string::ToString::to_string)
690→                    .collect::<Vec<_>>(),
691→            )),
692→            Arc::new(UInt64Array::from(query_execution_count)),
693→            Arc::new(Float64Array::from(memory_usage)),
694→        ];
695→
696→        if !extended_metrics_fields.is_empty() {
697→            let mut extended_metrics_builders =
698→                self.build_extended_metrics(vec![self.run_metric.as_ref()].into_iter())?;
699→
700→            for field in extended_metrics_field_names {
701→                match extended_metrics_builders.get_mut(field) {
702→                    Some(Builder::String(builder)) => columns.push(Arc::new(builder.finish())),
703→                    Some(Builder::UInt64(builder)) => columns.push(Arc::new(builder.finish())),
704→                    Some(Builder::Float64(builder)) => columns.push(Arc::new(builder.finish())),
705→                    None => {
706→                        return Err(anyhow::anyhow!(
707→                            "No builder found for extended metric field: {field}"
708→                        ));
709→                    }
710→                }
711→            }
712→        }
713→
714→        Ok(vec![RecordBatch::try_new(Self::run_schema(), columns)?])
715→    }
716→
717→    pub fn show_run(&self, status: Option<QueryStatus>) -> Result<()> {
718→        print_batches(&self.build_run(&status.unwrap_or_default())?)?;
719→
720→        Ok(())
721→    }
722→}
