724→pub trait MetricCollector<T: ExtendedMetrics, R: ExtendedMetrics> {
725→    fn start_time(&self) -> SystemTime;
726→    fn end_time(&self) -> SystemTime;
727→    fn name(&self) -> String;
728→    fn spiced_version(&self) -> Result<&str>;
729→    fn metrics(&self) -> Result<Vec<QueryMetric<T>>>;
730→    fn collect(&self, test_type: TestType) -> Result<QueryMetrics<T, R>> {
731→        Ok(QueryMetrics {
732→            run_id: uuid::Uuid::new_v4(),
733→            run_name: self.name(),
734→            spiced_version: self.spiced_version()?.to_string(),
735→            commit_sha: git::get_commit_sha(),
736→            branch_name: git::get_branch_name(),
737→            test_type,
738→            started_at: usize::try_from(
739→                self.start_time()
740→                    .duration_since(SystemTime::UNIX_EPOCH)?
741→                    .as_millis(),
742→            )?,
743→            finished_at: usize::try_from(
744→                self.end_time()
745→                    .duration_since(SystemTime::UNIX_EPOCH)?
746→                    .as_millis(),
747→            )?,
748→            metrics: self.metrics()?,
749→            memory_usage: None,
750→            run_metric: None,
751→        })
752→    }
753→}
