887→
888→        let second_percentile = durations
889→            .percentile(50.0)
890→            .expect("percentile should calculate");
891→        assert_eq!(second_percentile, std::time::Duration::from_secs(3));
892→
893→        let first_percentile = durations
894→            .percentile(25.0)
