897→
898→        let zero_percentile = durations
899→            .percentile(0.0)
900→            .expect("percentile should calculate");
901→        assert_eq!(zero_percentile, std::time::Duration::from_secs(1));
902→
903→        let hundred_percentile = durations
904→            .percentile(100.0)
905→            .expect("percentile should calculate");
906→        assert_eq!(hundred_percentile, std::time::Duration::from_secs(5));
907→    }
