 766→            let queries: Vec<Query> = remove_tpcds_query!(
 767→                queries, 1, 8,  // EXCEPT and INTERSECT aren't supported
 768→                4, // slow postgresql performance: https://www.postgresql.org/message-id/9A28C8860F777E439AA12E8AEA7694F801133F57%40BPXM15GP.gisp.nec.co.jp\
 769→                16, // slow postgresql performance
 770→                30, // https://github.com/spiceai/spiceai/issues/2939
 771→                36, // overridden below
 772→                38, // EXCEPT and INTERSECT aren't supported
 773→                64, // https://github.com/spiceai/spiceai/issues/2939
 774→                70, // overridden below
 775→                81, // https://github.com/spiceai/spiceai/issues/2939
 776→                86, // overridden below
 777→                87  // EXCEPT and INTERSECT aren't supported
 778→            );
 779→            add_tpcds_query_overrides!(queries, "postgres", 36, 70, 86)
 780→        }
 781→        Some(QueryOverrides::Spicecloud) => remove_tpcds_query!(
 782→            queries, 8,  // https://github.com/spiceai/spiceai/issues/4668
 783→            38, // https://github.com/spiceai/spiceai/issues/4667
 784→            87, // https://github.com/spiceai/spiceai/issues/4667
 785→            32, 92, // https://github.com/spiceai/spiceai/issues/8150
 786→            29, 37, 41, 44, 54, 58 // empty results
 787→        ),
 788→        Some(QueryOverrides::SQLite) => remove_tpcds_query!(
 789→            queries, 17, 29, 35, 74, // SQLite does not support `stddev`
 790→            5, 14, 18, 22, 27, 36, 67, 70, 77, 80,
 791→            86, // SQLite does not support `ROLLUP` and `GROUPING`
 792→            8, 14, 38, 87 // EXCEPT and INTERSECT aren't supported
 793→        ),
 794→        Some(QueryOverrides::Spark) => remove_tpcds_query!(
 795→            queries, 8, // https://github.com/spiceai/spiceai/issues/5250
 796→            36, 44, 47, 49, 57, 67, 70, 86, // https://github.com/spiceai/spiceai/issues/5249
 797→            38, 87, // https://github.com/spiceai/spiceai/issues/5247
 798→            6, 32, 92 // https://github.com/spiceai/spiceai/issues/5246
 799→        ),
 800→        Some(QueryOverrides::ODBCDatabricks) => {
 801→            let queries: Vec<Query> = remove_tpcds_query!(
 802→                queries, 6, 8, 13, 14, 23, 24, 32, 36, 38, 39, 44, 47, 49, 57, 67, 70, 86, 87, 91,
 803→                92
 804→            );
 805→
 806→            add_tpcds_query_overrides!(
 807→                queries,
 808→                "odbc_databricks",
 809→                6,
 810→                32,
 811→                36,
 812→                44,
 813→                47,
 814→                49,
 815→                57,
 816→                67,
 817→                70,
 818→                86,
 819→                92
 820→            )
 821→        }
 822→        Some(QueryOverrides::Dremio) => remove_tpcds_query!(
 823→            queries, 8, 38, 87, // LEFT SEMI, and LEFT ANTI
 824→            64  // OUT_OF_MEMORY ERROR https://github.com/spiceai/spiceai/issues/8765
 825→        ),
 826→        Some(_) | None => queries,
 827→    }
 828→}
