 17→use std::sync::Arc;
 18→
 19→use arrow::datatypes::DataType;
 20→
 21→use super::Query;
 22→
 23→// DataFusion has ParamValues which can define a list of `Vec<ScalarValue>`
 24→// This is a scaled down equivalent to the `ScalarValue` enum, but we don't want to import DataFusion just for this.
 25→#[derive(Debug, Clone, PartialEq)]
 26→pub enum ParameterValue {
 27→    String(Arc<str>),
 28→    Number(i64),
 29→    Float(f64),
 30→}
 31→
 32→impl ParameterValue {
 33→    #[must_use]
 34→    pub fn dtype(&self) -> DataType {
 35→        match self {
 36→            ParameterValue::String(_) => DataType::Utf8,
 37→            ParameterValue::Number(_) => DataType::Int64,
 38→            ParameterValue::Float(_) => DataType::Float64,
 39→        }
 40→    }
 41→
 42→    #[must_use]
 43→    pub fn array(&self) -> Arc<dyn arrow::array::Array> {
 44→        match self {
 45→            ParameterValue::String(value) => {
 46→                Arc::new(arrow::array::StringArray::from(vec![value.as_ref()]))
 47→            }
 48→            ParameterValue::Number(value) => Arc::new(arrow::array::Int64Array::from(vec![*value])),
 49→            ParameterValue::Float(value) => {
 50→                #[expect(clippy::cast_possible_truncation)]
 51→                let decimal_value = (*value * 1_000_000.0) as i128;
 52→                Arc::new(arrow::array::Decimal128Array::from(vec![decimal_value]))
 53→            }
 54→        }
 55→    }
 56→
 57→    /// Converts the parameter value to a SQL literal string for use in queries
 58→    /// that don't support parameterized queries (e.g., HTTP endpoints).
 59→    #[must_use]
 60→    pub fn to_sql_literal(&self) -> String {
 61→        match self {
 62→            ParameterValue::String(s) => format!("'{}'", s.replace('\'', "''")),
 63→            ParameterValue::Number(n) => n.to_string(),
 64→            ParameterValue::Float(f) => f.to_string(),
 65→        }
 66→    }
 67→}
 68→
 69→/// Defines parameters for TPC-H queries. Values are extracted from the original TPC-H queries,
 70→/// with their values replaced with $1 parameters in the `/parameterized/` TPC-H files.
 71→#[must_use]
 72→pub fn add_tpch_parameters(queries: Vec<Query>) -> Vec<Query> {
 73→    queries
 74→        .into_iter()
 75→        .map(|q| {
 76→            let mut q = q;
 77→            match q.name.replace("tpch_", "").as_str() {
 78→                "q1" => q.parameters = Some(vec![ParameterValue::String("1998-09-02".into())]),
 79→                "q2" => {
 80→                    q.parameters = Some(vec![
 81→                        ParameterValue::Number(15),
 82→                        ParameterValue::String("%BRASS".into()),
 83→                        ParameterValue::String("EUROPE".into()),
 84→                        ParameterValue::String("EUROPE".into()),
 85→                    ]);
 86→                }
 87→                "q3" => {
 88→                    q.parameters = Some(vec![ParameterValue::String("BUILDING".into())]);
 89→                }
 90→                "q5" => {
 91→                    q.parameters = Some(vec![ParameterValue::String("ASIA".into())]);
 92→                }
 93→                "q6" => {
 94→                    q.parameters = Some(vec![
 95→                        ParameterValue::Float(0.06),
 96→                        ParameterValue::Float(0.01),
 97→                        ParameterValue::Float(0.06),
 98→                        ParameterValue::Float(0.01),
 99→                        ParameterValue::Number(24),
100→                    ]);
101→                }
102→                "q7" => {
103→                    q.parameters = Some(vec![
104→                        ParameterValue::String("FRANCE".into()),
105→                        ParameterValue::String("GERMANY".into()),
106→                        ParameterValue::String("GERMANY".into()),
107→                        ParameterValue::String("FRANCE".into()),
108→                    ]);
109→                }
110→                "q8" => {
111→                    q.parameters = Some(vec![
112→                        ParameterValue::String("BRAZIL".into()),
113→                        ParameterValue::String("AMERICA".into()),
114→                        ParameterValue::String("ECONOMY ANODIZED STEEL".into()),
115→                    ]);
116→                }
117→                "q9" => {
118→                    q.parameters = Some(vec![ParameterValue::String("%green%".into())]);
119→                }
120→                "q10" => {
