 17→use std::{collections::HashMap, path::Path, sync::Arc};
 18→
 19→use arrow::array::RecordBatch;
 20→use serde::{Deserialize, Serialize};
 21→
 22→use super::Query;
 23→
 24→/// A scenario query definition that can be loaded from a YAML file
 25→#[derive(Debug, Clone, Deserialize, Serialize, PartialEq)]
 26→pub struct ScenarioQueryDefinition {
 27→    /// Unique name for the query
 28→    pub name: String,
 29→
 30→    /// SQL query to execute
 31→    pub sql: String,
 32→
 33→    /// Optional expected results for validation
 34→    /// Can be specified as a path to a CSV file or inline data
 35→    #[serde(skip_serializing_if = "Option::is_none")]
 36→    pub expected_results: Option<ExpectedResults>,
 37→}
 38→
 39→/// Expected results for query validation
 40→#[derive(Debug, Clone, Deserialize, Serialize, PartialEq)]
 41→#[serde(untagged)]
 42→pub enum ExpectedResults {
 43→    /// Path to a CSV file containing expected results
 44→    FilePath(String),
 45→
 46→    /// Inline structured data with columns and rows (comma-delimited strings)
 47→    InlineData { columns: String, rows: Vec<String> },
 48→
 49→    /// Inline CSV data as a string (legacy support)
 50→    InlineCSV(String),
 51→
 52→    /// Expected row count only (for cases where you just want to verify row count)
 53→    RowCount { row_count: usize },
 54→}
 55→
 56→/// A collection of scenario queries loaded from a file
 57→#[derive(Debug, Clone, Deserialize, Serialize, PartialEq)]
 58→pub struct ScenarioQuerySet {
 59→    /// Optional name for the query set
 60→    #[serde(skip_serializing_if = "Option::is_none")]
 61→    pub name: Option<String>,
 62→
 63→    /// List of queries in this set
 64→    pub queries: Vec<ScenarioQueryDefinition>,
 65→}
 66→
 67→impl ScenarioQuerySet {
 68→    /// Load a scenario query set from a YAML file
 69→    pub fn from_file(path: impl AsRef<Path>) -> anyhow::Result<Self> {
 70→        let content = std::fs::read_to_string(path.as_ref())?;
 71→        let query_set: ScenarioQuerySet = yaml::from_str(&content)?;
 72→        Ok(query_set)
 73→    }
 74→
 75→    /// Convert scenario query definitions into Query objects
 76→    #[must_use]
 77→    pub fn into_queries(self) -> Vec<Query> {
 78→        self.queries
 79→            .into_iter()
 80→            .map(|def| Query::new(def.name.into(), def.sql.into(), false))
 81→            .collect()
 82→    }
 83→
 84→    /// Get expected results for validation (as `RecordBatches`)
 85→    /// Returns a map of query name to expected results
 86→    pub fn get_expected_results(
 87→        &self,
 88→        base_path: Option<&Path>,
 89→    ) -> anyhow::Result<HashMap<Arc<str>, Vec<RecordBatch>>> {
 90→        let mut results = HashMap::new();
 91→
 92→        for query in &self.queries {
 93→            if let Some(expected) = &query.expected_results {
 94→                let batches = match expected {
 95→                    ExpectedResults::FilePath(path) => {
 96→                        let full_path = if let Some(base) = base_path {
 97→                            base.join(path)
 98→                        } else {
 99→                            Path::new(path).to_path_buf()
100→                        };
101→                        load_csv_as_batches(&full_path)?
102→                    }
103→                    ExpectedResults::InlineData { columns, rows } => {
104→                        load_from_structured_data(columns, rows)?
105→                    }
106→                    ExpectedResults::InlineCSV(csv_data) => load_csv_from_string(csv_data)?,
107→                    ExpectedResults::RowCount { .. } => {
108→                        // Row count validation is handled separately
109→                        continue;
110→                    }
111→                };
112→
113→                results.insert(Arc::from(query.name.as_str()), batches);
114→            }
115→        }
116→
117→        Ok(results)
118→    }
119→
120→    /// Get expected row counts for queries that only specify row count validation
121→    #[must_use]
122→    pub fn get_expected_row_counts(&self) -> HashMap<Arc<str>, usize> {
123→        let mut counts = HashMap::new();
124→
125→        for query in &self.queries {
126→            if let Some(ExpectedResults::RowCount { row_count }) = &query.expected_results {
127→                counts.insert(Arc::from(query.name.as_str()), *row_count);
128→            }
129→        }
130→
131→        counts
132→    }
133→}
134→
135→/// Load CSV file as Arrow `RecordBatches`
136→fn load_csv_as_batches(path: &Path) -> anyhow::Result<Vec<RecordBatch>> {
137→    use arrow::csv::ReaderBuilder;
138→    use arrow::csv::reader::Format;
139→    use std::io::Seek;
140→
141→    let mut file = std::fs::File::open(path)?;
142→    let format = Format::default().with_header(true);
143→    let (schema, _) = format.infer_schema(&mut file, None)?;
144→    file.rewind()?;
145→
146→    let reader = ReaderBuilder::new(Arc::new(schema))
147→        .with_format(format)
148→        .build(file)?;
149→
150→    let mut batches = Vec::new();
151→    for batch in reader {
152→        batches.push(batch?);
153→    }
154→
155→    Ok(batches)
156→}
157→
158→/// Load CSV from string as Arrow `RecordBatches`
159→fn load_csv_from_string(csv_data: &str) -> anyhow::Result<Vec<RecordBatch>> {
160→    use arrow::csv::ReaderBuilder;
161→    use arrow::csv::reader::Format;
162→    use std::io::{Cursor, Seek};
163→
164→    let mut cursor = Cursor::new(csv_data.as_bytes());
165→    let format = Format::default().with_header(true);
166→    let (schema, _) = format.infer_schema(&mut cursor, None)?;
167→    cursor.rewind()?;
168→
169→    let reader = ReaderBuilder::new(Arc::new(schema))
170→        .with_format(format)
171→        .build(cursor)?;
172→
173→    let mut batches = Vec::new();
174→    for batch in reader {
175→        batches.push(batch?);
176→    }
177→
178→    Ok(batches)
179→}
180→
181→/// Load structured data (columns + rows) as Arrow `RecordBatches`
182→/// Columns and rows are comma-delimited strings
183→fn load_from_structured_data(
184→    columns_str: &str,
185→    rows_str: &[String],
186→) -> anyhow::Result<Vec<RecordBatch>> {
187→    use arrow::csv::ReaderBuilder;
188→    use arrow::csv::reader::Format;
189→    use std::io::{Cursor, Seek};
190→
191→    // Parse column names
192→    let columns: Vec<&str> = columns_str.split(',').map(str::trim).collect();
193→
194→    if columns.is_empty() {
195→        return Ok(vec![]);
196→    }
197→
198→    // Build CSV string from columns and rows
199→    let mut csv_data = columns.join(",");
200→    csv_data.push('\n');
201→
202→    for row in rows_str {
203→        csv_data.push_str(row);
204→        csv_data.push('\n');
205→    }
206→
207→    // Parse CSV data
208→    let mut cursor = Cursor::new(csv_data.as_bytes());
209→    let format = Format::default().with_header(true);
210→    let (schema, _) = format.infer_schema(&mut cursor, None)?;
211→    cursor.rewind()?;
212→
213→    let reader = ReaderBuilder::new(Arc::new(schema))
214→        .with_format(format)
215→        .build(cursor)?;
216→
217→    let mut batches = Vec::new();
218→    for batch in reader {
219→        batches.push(batch?);
220→    }
221→
222→    Ok(batches)
223→}
