231→        let yaml = r#"
232→name: test_queries
233→queries:
234→  - name: simple_select
235→    sql: SELECT * FROM test_table
236→  - name: count_query
237→    sql: SELECT COUNT(*) FROM test_table
238→    expected_results:
239→      row_count: 1
240→  - name: with_structured_data
241→    sql: SELECT id, name FROM users
242→    expected_results:
243→      columns: "id, name"
244→      rows:
