 128→fn datatype_equivalent(expected_type: &DataType, actual_type: &DataType) -> bool {
 129→    if expected_type == actual_type {
 130→        return true;
 131→    }
 132→
 133→    // Check for logical equivalence, with a lenient set of rules
 134→    // E.g. a number could be returned as a string, number, or float.
 135→    match (expected_type, actual_type) {
 136→        // Handle timestamp timezone differences
 137→        (DataType::Timestamp(unit1, tz1), DataType::Timestamp(unit2, tz2)) => {
 138→            // Same time unit is required
 139→            if unit1 != unit2 {
 140→                return false;
 141→            }
 142→            // Allow timezone differences between None and Some("UTC")
 143→            matches!(
 144→                (tz1.as_deref(), tz2.as_deref()),
 145→                (None, Some("UTC" | "+00:00")) | (Some("UTC" | "+00:00"), None)
 146→            )
 147→        }
 148→        // Existing numeric and string type equivalences
 149→        _ => matches!(
 150→            (expected_type, actual_type),
 151→            (DataType::Float32, DataType::Float64)
 152→                | (
 153→                    DataType::Float64 | DataType::Int64,
 154→                    DataType::Decimal128(_, _)
 155→                )
 156→                | (DataType::Int32, DataType::Int64)
 157→                | (
 158→                    DataType::Int64,
 159→                    DataType::Int32
 160→                        | DataType::Int8
 161→                        | DataType::Float64
 162→                        | DataType::Utf8
 163→                        | DataType::LargeUtf8
 164→                        | DataType::Utf8View
 165→                )
 166→                | (DataType::Utf8, DataType::LargeUtf8)
 167→                | (DataType::LargeUtf8, DataType::Utf8)
 168→                | (DataType::Date32, DataType::Date64)
 169→                | (DataType::Date64, DataType::Date32)
 170→        ),
 171→    }
 172→}
 173→
 174→fn equivalent_schemas(expected_schema: &SchemaRef, actual_schema: &SchemaRef) -> bool {
 175→    if expected_schema.fields().len() != actual_schema.fields().len() {
 176→        return false;
 177→    }
 178→
 179→    expected_schema
 180→        .fields()
 181→        .iter()
 182→        .zip(actual_schema.fields().iter())
 183→        .all(|(f1, f2)| datatype_equivalent(f1.data_type(), f2.data_type()))
 184→}
