 186→macro_rules! downcast_and_stringify {
 187→    ($array:expr, $index:expr, $t:ty) => {{
 188→        Ok(Some(
 189→            $array
 190→                .as_any()
 191→                .downcast_ref::<$t>()
 192→                .ok_or_else(|| anyhow!("Failed to downcast array"))?
 193→                .value($index)
 194→                .to_string(),
 195→        ))
 196→    }};
 197→}
 198→
 199→macro_rules! downcast_and_stringify_ts {
 200→    ($array:expr, $index:expr, $t:ty, $scale:expr, $format:expr) => {{
 201→        let ts = $array
 202→            .as_any()
 203→            .downcast_ref::<$t>()
 204→            .ok_or_else(|| anyhow!("Failed to downcast timestamp array"))?
 205→            .value($index);
 206→        let secs = ts / $scale;
 207→        let sub = ts.rem_euclid($scale);
 208→        let sub_u32 = u32::try_from(sub)
 209→            .map_err(|_| anyhow!("Subsecond value out of range for u32: {}", sub))?;
 210→        let nanos = sub_u32 * (1_000_000_000u32 / $scale as u32);
 211→        let dt = DateTime::from_timestamp(secs, nanos)
 212→            .ok_or_else(|| anyhow!("Invalid timestamp from seconds={} nanos={}", secs, nanos))?;
 213→        Ok(Some(dt.format($format).to_string()))
 214→    }};
 215→}
