 217→/// Converts a value from an Arrow `Array` at a specific index into its string representation.
 218→///
 219→/// Designed not to be used for production stringification, but rather for producing consistent values for validation results.
 220→/// Using input `RecordBatch` values, it attempts to remove any system differences from underlying sources (e.g. timestamp formats, etc).
 221→///
 222→/// # Parameters:
 223→/// - `array`: A reference to a dynamically typed Arrow `Array`. This is the array that holds the data.
 224→/// - `index`: The index of the value to convert to a string.
 225→///
 226→/// # Returns:
 227→/// - `Ok(Some(String))`: A string representation of the value at the specified index.
 228→/// - `Ok(None)`: If the value is `null` at the given index, or the type is not implemented for conversion.
 229→/// - `Err(anyhow::Error)`: If there is an error (e.g., invalid index, failed downcast).
 230→///
 231→/// # Example:
 232→/// ```rust,ignore
 233→/// use arrow::array::Int64Array;
 234→/// let array = Int64Array::from(vec![12345]);
 235→/// let result = array_value_to_string(&array, 0);
 236→/// assert_eq!(result.unwrap(), Some("12345".to_string()));
 237→/// ```
 238→///
 239→/// # Error Handling:
 240→/// - If the `index` is out of bounds, the function returns an error indicating the invalid index.
 241→/// - If the value at the index is `null`, `None` is returned.
 242→/// - If the function fails to downcast the array to the expected type (e.g., if the array's type is
 243→///   mismatched), it will return an error.
 244→/// - If the array's data type is not supported for conversion, `None` is returned.
 245→pub fn array_value_to_string(array: &dyn Array, index: usize) -> Result<Option<String>> {
 246→    if array.len() <= index {
 247→        return Err(anyhow!("Index out of bounds: {index} >= {}", array.len()));
 248→    }
 249→
 250→    if array.is_null(index) {
 251→        return Ok(None);
 252→    }
 253→
 254→    match array.data_type() {
 255→        DataType::Int64 => downcast_and_stringify!(array, index, Int64Array),
 256→        DataType::Int32 => downcast_and_stringify!(array, index, Int32Array),
 257→        DataType::Int16 => downcast_and_stringify!(array, index, Int16Array),
 258→        DataType::Int8 => downcast_and_stringify!(array, index, Int8Array),
 259→        DataType::UInt64 => downcast_and_stringify!(array, index, UInt64Array),
 260→        DataType::UInt32 => downcast_and_stringify!(array, index, UInt32Array),
 261→        DataType::UInt16 => downcast_and_stringify!(array, index, UInt16Array),
 262→        DataType::UInt8 => downcast_and_stringify!(array, index, UInt8Array),
 263→        DataType::Float32 => downcast_and_stringify!(array, index, Float32Array),
 264→        DataType::Float64 => downcast_and_stringify!(array, index, Float64Array),
 265→        DataType::Utf8 => downcast_and_stringify!(array, index, StringArray),
 266→        DataType::LargeUtf8 => downcast_and_stringify!(array, index, LargeStringArray),
 267→        DataType::Utf8View => downcast_and_stringify!(array, index, StringViewArray),
 268→        DataType::Boolean => downcast_and_stringify!(array, index, BooleanArray),
 269→
 270→        DataType::Date32 => {
 271→            let days = array
 272→                .as_any()
 273→                .downcast_ref::<Date32Array>()
 274→                .ok_or_else(|| anyhow!("Failed to downcast Date32 array"))?
 275→                .value(index);
 276→            let date = NaiveDate::from_ymd_opt(1970, 1, 1)
 277→                .ok_or_else(|| anyhow!("Invalid base date"))?
 278→                .checked_add_signed(chrono::Duration::days(i64::from(days)))
 279→                .ok_or_else(|| anyhow!("Date out of range"))?;
 280→            Ok(Some(date.format("%Y-%m-%d").to_string()))
 281→        }
 282→
 283→        DataType::Date64 => {
 284→            let millis = array
 285→                .as_any()
 286→                .downcast_ref::<Date64Array>()
 287→                .ok_or_else(|| anyhow!("Failed to downcast Date64 array"))?
 288→                .value(index);
 289→            let days = millis / 86_400_000; // Convert milliseconds to days
 290→            let date = NaiveDate::from_ymd_opt(1970, 1, 1)
 291→                .ok_or_else(|| anyhow!("Invalid base date"))?
 292→                .checked_add_signed(chrono::Duration::days(days))
 293→                .ok_or_else(|| anyhow!("Date out of range"))?;
 294→            Ok(Some(date.format("%Y-%m-%d").to_string()))
 295→        }
 296→
 297→        DataType::Decimal128(_, scale) => {
 298→            let val = array
 299→                .as_any()
 300→                .downcast_ref::<Decimal128Array>()
 301→                .ok_or_else(|| anyhow!("Failed to downcast Decimal128 array"))?
 302→                .value(index);
 303→
 304→            let sign = if val < 0 { "-" } else { "" };
 305→            let abs_val = val.abs();
 306→            let scale = usize::try_from(*scale)?; // Convert scale to usize
 307→
 308→            let str_val = abs_val.to_string(); // Convert the absolute value to a string
 309→
 310→            // Split the string into integer and fractional parts
 311→            let len = str_val.len();
 312→            let (int_part, frac_part) = if len > scale {
 313→                let (a, b) = str_val.split_at(len - scale);
 314→                (a.to_string(), b.to_string())
 315→            } else {
 316→                ("0".to_string(), format!("{str_val:0>scale$}"))
 317→            };
 318→
 319→            if frac_part.is_empty() {
 320→                Ok(Some(format!("{sign}{int_part}")))
 321→            } else {
 322→                Ok(Some(format!("{sign}{int_part}.{frac_part}")))
 323→            }
 324→        }
 325→
 326→        DataType::Timestamp(unit, _) => match unit {
 327→            TimeUnit::Second => {
 328→                let ts = array
 329→                    .as_any()
 330→                    .downcast_ref::<TimestampSecondArray>()
 331→                    .ok_or_else(|| anyhow!("Failed to downcast TimestampSecondArray"))?
 332→                    .value(index);
 333→                let dt = DateTime::from_timestamp(ts, 0)
 334→                    .ok_or_else(|| anyhow!("Invalid timestamp for seconds={ts}"))?;
 335→                Ok(Some(dt.format("%Y-%m-%d %H:%M:%S").to_string()))
 336→            }
 337→            TimeUnit::Millisecond => {
 338→                let ts = array
 339→                    .as_any()
 340→                    .downcast_ref::<TimestampMillisecondArray>()
 341→                    .ok_or_else(|| anyhow!("Failed to downcast TimestampMillisecondArray"))?
 342→                    .value(index);
 343→                let secs = ts / 1000;
 344→                let sub_ms = ts.rem_euclid(1000);
 345→                let sub_u32 = u32::try_from(sub_ms)?;
 346→                let nanos = sub_u32 * 1_000_000;
 347→                let dt = DateTime::from_timestamp(secs, nanos)
 348→                    .ok_or_else(|| anyhow!("Invalid timestamp"))?;
 349→                Ok(Some(dt.format("%Y-%m-%d %H:%M:%S%.3f").to_string()))
 350→            }
 351→            TimeUnit::Microsecond => {
 352→                downcast_and_stringify_ts!(
 353→                    array,
 354→                    index,
 355→                    TimestampMicrosecondArray,
 356→                    1_000_000,
 357→                    "%Y-%m-%d %H:%M:%S%.6f"
 358→                )
 359→            }
 360→            TimeUnit::Nanosecond => {
 361→                downcast_and_stringify_ts!(
 362→                    array,
 363→                    index,
 364→                    TimestampNanosecondArray,
 365→                    1_000_000_000,
 366→                    "%Y-%m-%d %H:%M:%S%.9f"
 367→                )
 368→            }
 369→        },
 370→
 371→        dt => Err(anyhow::anyhow!(
 372→            "Unsupported data type for validation: {dt:?}",
 373→        )),
 374→    }
 375→}
