 377→pub fn validate_batches_as_strings(
 378→    expected: &RecordBatch,
 379→    actual: &RecordBatch,
 380→) -> Result<QueryValidationResult> {
 381→    let schema = expected.schema();
 382→
 383→    for (i, field) in schema.fields().iter().enumerate() {
 384→        let column_name = field.name().clone();
 385→        let data_type = field.data_type();
 386→        let expected_array = expected.column(i).as_ref();
 387→        let actual_array = actual.column(i).as_ref();
 388→
 389→        if expected_array.len() != actual_array.len() {
 390→            return Ok(QueryValidationResult::Fail(
 391→                QueryValidationFailReason::ColumnLengthMismatch {
 392→                    column_name,
 393→                    left_len: expected_array.len(),
 394→                    right_len: actual_array.len(),
 395→                },
 396→            ));
 397→        }
 398→
 399→        for row in 0..expected_array.len() {
 400→            let expected_val = array_value_to_string(expected_array, row)?;
 401→            let actual_val = array_value_to_string(actual_array, row)?;
 402→
 403→            match (expected_val, actual_val) {
 404→                (None, None) => {}
 405→                (Some(val), None) => {
 406→                    return Ok(QueryValidationResult::Fail(
 407→                        QueryValidationFailReason::DataMismatch {
 408→                            column: column_name,
 409→                            row_number: row + 1, // indexes are 0-based, counts are 1-based
 410→                            expected: format!("{val:?}"),
 411→                            actual: "None".to_string(),
 412→                        },
 413→                    ));
 414→                }
 415→                (None, Some(val)) => {
 416→                    return Ok(QueryValidationResult::Fail(
 417→                        QueryValidationFailReason::DataMismatch {
 418→                            column: column_name,
 419→                            row_number: row + 1, // indexes are 0-based, counts are 1-based
 420→                            expected: "None".to_string(),
 421→                            actual: format!("{val:?}"),
 422→                        },
 423→                    ));
 424→                }
 425→                (Some(expected_val), Some(actual_val)) => {
 426→                    if expected_val != actual_val {
 427→                        if data_type.is_numeric() {
 428→                            let delta = 0.05;
 429→
 430→                            if let (Ok(expected_num), Ok(actual_num)) =
 431→                                (expected_val.parse::<f64>(), actual_val.parse::<f64>())
 432→                            {
 433→                                let diff = (expected_num - actual_num).abs();
 434→                                let tolerance = (expected_num.abs() * delta).max(1e-12); // avoid zero-multiplied tolerance
 435→                                if diff <= tolerance {
 436→                                    continue; // numeric match within tolerance
 437→                                }
 438→                            }
 439→                        }
 440→
 441→                        return Ok(QueryValidationResult::Fail(
 442→                            QueryValidationFailReason::DataMismatch {
 443→                                column: column_name,
 444→                                row_number: row + 1, // indexes are 0-based, counts are 1-based
 445→                                expected: format!("{expected_val:?}"),
 446→                                actual: format!("{actual_val:?}"),
 447→                            },
 448→                        ));
 449→                    }
 450→                }
 451→            }
 452→        }
 453→    }
 454→
 455→    Ok(QueryValidationResult::Pass)
 456→}
