 458→pub fn validate_tpch_query(
 459→    query: &Query,
 460→    batches: &[RecordBatch],
 461→) -> Result<QueryValidationResult> {
 462→    let Some(expected_batches) = TPCH_ANSWERS.get(&query.name) else {
 463→        return Ok(QueryValidationResult::Fail(
 464→            QueryValidationFailReason::NoExpectedAnswer,
 465→        ));
 466→    };
 467→
 468→    match (expected_batches.is_empty(), batches.is_empty()) {
 469→        (true, true) | (false, false) => {}
 470→        (true, false) => {
 471→            return Ok(QueryValidationResult::Fail(
 472→                QueryValidationFailReason::NoExpectedAnswer,
 473→            ));
 474→        }
 475→        _ => {
 476→            return Ok(QueryValidationResult::Fail(
 477→                QueryValidationFailReason::NoAnswer,
 478→            ));
 479→        }
 480→    }
 481→
 482→    let Some(expected_schema) = expected_batches
 483→        .first()
 484→        .map(arrow::array::RecordBatch::schema)
 485→    else {
 486→        return Ok(QueryValidationResult::Fail(
 487→            QueryValidationFailReason::NoAnswer,
 488→        ));
 489→    };
 490→    let Some(actual_schema) = batches.first().map(arrow::array::RecordBatch::schema) else {
 491→        return Ok(QueryValidationResult::Fail(
 492→            QueryValidationFailReason::NoAnswer,
 493→        ));
 494→    };
 495→
 496→    if !equivalent_schemas(&expected_schema, &actual_schema) {
 497→        println!("expected_schema: {expected_schema:?}");
 498→        println!("actual_schema: {actual_schema:?}");
 499→
 500→        return Ok(QueryValidationResult::Fail(
 501→            QueryValidationFailReason::SchemaMismatch,
 502→        ));
 503→    }
 504→
 505→    // combine all expected batches and all actual batches into a single RecordBatch
 506→    let expected_batches = arrow::compute::concat_batches(&expected_schema, expected_batches)?;
 507→    let actual_batches = arrow::compute::concat_batches(&actual_schema, batches)?;
 508→
 509→    // check the row counts are equal
 510→    if expected_batches.num_rows() != actual_batches.num_rows() {
 511→        return Ok(QueryValidationResult::Fail(
 512→            QueryValidationFailReason::RowCountMismatch {
 513→                expected: expected_batches.num_rows(),
 514→                actual: actual_batches.num_rows(),
 515→            },
 516→        ));
 517→    }
 518→
 519→    // check the actual data batches are equal
 520→    validate_batches_as_strings(&expected_batches, &actual_batches)
 521→}
