 523→/// Validate a query against expected results from a custom query set
 524→/// This is a generic validation function that can be used for custom queries
 525→pub fn validate_with_expected_batches(
 526→    query_name: &str,
 527→    actual_batches: &[RecordBatch],
 528→    expected_batches: &[RecordBatch],
 529→) -> Result<QueryValidationResult> {
 530→    if expected_batches.is_empty() && actual_batches.is_empty() {
 531→        return Ok(QueryValidationResult::Pass);
 532→    }
 533→
 534→    if expected_batches.is_empty() {
 535→        return Ok(QueryValidationResult::Fail(
 536→            QueryValidationFailReason::NoExpectedAnswer,
 537→        ));
 538→    }
 539→
 540→    if actual_batches.is_empty() {
 541→        return Ok(QueryValidationResult::Fail(
 542→            QueryValidationFailReason::NoAnswer,
 543→        ));
 544→    }
 545→
 546→    let Some(expected_schema) = expected_batches
 547→        .first()
 548→        .map(arrow::array::RecordBatch::schema)
 549→    else {
 550→        return Ok(QueryValidationResult::Fail(
 551→            QueryValidationFailReason::NoAnswer,
 552→        ));
 553→    };
 554→
 555→    let Some(actual_schema) = actual_batches
 556→        .first()
 557→        .map(arrow::array::RecordBatch::schema)
 558→    else {
 559→        return Ok(QueryValidationResult::Fail(
 560→            QueryValidationFailReason::NoAnswer,
 561→        ));
 562→    };
 563→
 564→    if !equivalent_schemas(&expected_schema, &actual_schema) {
 565→        println!("Query '{query_name}' schema mismatch:");
 566→        println!("  expected_schema: {expected_schema:?}");
 567→        println!("  actual_schema: {actual_schema:?}");
 568→
 569→        return Ok(QueryValidationResult::Fail(
 570→            QueryValidationFailReason::SchemaMismatch,
 571→        ));
 572→    }
 573→
 574→    // combine all expected batches and all actual batches into a single RecordBatch
 575→    let expected_batches = arrow::compute::concat_batches(&expected_schema, expected_batches)?;
 576→    let actual_batches = arrow::compute::concat_batches(&actual_schema, actual_batches)?;
 577→
 578→    // check the row counts are equal
 579→    if expected_batches.num_rows() != actual_batches.num_rows() {
 580→        println!("Query '{query_name}' row count mismatch:");
 581→        println!("  expected: {}", expected_batches.num_rows());
 582→        println!("  actual: {}", actual_batches.num_rows());
 583→
 584→        return Ok(QueryValidationResult::Fail(
 585→            QueryValidationFailReason::RowCountMismatch {
 586→                expected: expected_batches.num_rows(),
 587→                actual: actual_batches.num_rows(),
 588→            },
 589→        ));
 590→    }
 591→
 592→    validate_batches_as_strings(&expected_batches, &actual_batches)
 593→}
