 595→/// Validate that actual batches have the expected row count
 596→pub fn validate_row_count(
 597→    query_name: &str,
 598→    actual_batches: &[RecordBatch],
 599→    expected_row_count: usize,
 600→) -> Result<QueryValidationResult> {
 601→    let actual_row_count: usize = actual_batches.iter().map(RecordBatch::num_rows).sum();
 602→
 603→    if actual_row_count == expected_row_count {
 604→        Ok(QueryValidationResult::Pass)
 605→    } else {
 606→        println!("Query '{query_name}' row count mismatch:");
 607→        println!("  expected: {expected_row_count}");
 608→        println!("  actual: {actual_row_count}");
 609→
 610→        Ok(QueryValidationResult::Fail(
 611→            QueryValidationFailReason::RowCountMismatch {
 612→                expected: expected_row_count,
 613→                actual: actual_row_count,
 614→            },
 615→        ))
 616→    }
 617→}
