 17→use std::{panic, sync::Arc};
 18→
 19→use crate::{flight::query_to_batches, queries::Query};
 20→use flight_client::FlightClient;
 21→
 22→pub const CAYENNE_PATH_FILTER_PATTERN: &str =
 23→    r"(/data/[A-Za-z0-9_\-\[\]=]+)(?:/[A-Za-z0-9_\-\.\[\]=]+)+\.vortex";
 24→pub const CAYENNE_PATH_FILTER_REPLACEMENT: &str = "$1/<CAYENNE_PATH>.vortex";
 25→const VORTEX_RANGE_FILTER_PATTERN: &str = r"(\.vortex):\d+\.\.\d+";
 26→const VORTEX_RANGE_FILTER_REPLACEMENT: &str = "$1:<RANGE>";
 27→
 28→fn make_tmpdir_regex_pattern(tempdir: &str) -> String {
 29→    format!(r"(?:{tempdir}|private/{tempdir})/[^/]*/(\.spice/)?data")
 30→}
 31→
 32→pub async fn record_explain_plan(
 33→    flight_client: Arc<FlightClient>,
 34→    name: &str,
 35→    query: &Query,
 36→    scale_factor: f64,
 37→) -> anyhow::Result<()> {
 38→    // Check the plan
 39→    let query_name = Arc::clone(&query.name);
 40→    let plan_results = query_to_batches(
 41→        flight_client,
 42→        &format!("EXPLAIN {}", query.to_sql_with_inlined_params()),
 43→    )
 44→    .await
 45→    .map_err(|e| anyhow::anyhow!("query `{query_name}` to plan: {e}"))?;
 46→
 47→    let explain_plan_raw = arrow::util::pretty::pretty_format_batches(&plan_results)?;
 48→
 49→    // Sort PartitionedUnionExec children for deterministic snapshot comparison
 50→    let explain_plan = sort_partitioned_union_children(&explain_plan_raw.to_string());
 51→
 52→    let mut assertion_err: Option<String> = None;
 53→
 54→    let temp_dir = std::env::temp_dir();
 55→    let temp_dir_str = temp_dir.to_str().unwrap_or_default();
 56→    let temp_dir_clean = temp_dir_str.trim_end_matches('/').trim_start_matches('/');
 57→    let temp_dir_pattern = regex::escape(temp_dir_clean);
 58→
 59→    // Create two patterns:
 60→    // 1. Exact match starting with the temp_dir: {temp_dir}/some_dir/data
 61→    // 2. Match with "private" prefix: private{temp_dir}/some_dir/data
 62→    let path_filter_pattern = make_tmpdir_regex_pattern(temp_dir_pattern.as_str());
 63→
 64→    insta::with_settings!({
 65→        description => format!("Query: {query_name}"),
 66→        omit_expression => true,
 67→        snapshot_path => "snapshots/explain",
 68→        filters => vec![
 69→            (path_filter_pattern.as_str(), "/data"),
 70→            (CAYENNE_PATH_FILTER_PATTERN, CAYENNE_PATH_FILTER_REPLACEMENT),
 71→            (VORTEX_RANGE_FILTER_PATTERN, VORTEX_RANGE_FILTER_REPLACEMENT),
 72→            (r"required_guarantees=\[[^\]]*\]", "required_guarantees=[N]"),
 73→            (r#"grouping\((?:item|"item")\.(?:i_category|i_class|"i_category"|"i_class")\),\s*grouping\((?:item|"item")\.(?:i_category|i_class|"i_category"|"i_class")\)"#, "<GROUPING_PAIR>"),
 74→            (r#"grouping\((?:store|"store")\.(?:s_state|s_county|"s_state"|"s_county")\),\s*grouping\((?:store|"store")\.(?:s_state|s_county|"s_state"|"s_county")\)"#, "<GROUPING_PAIR>")
 75→        ],
 76→    }, {
 77→        let snapshot_name = if (scale_factor - 1.0).abs() < f64::EPSILON {
 78→            format!("{name}_{query_name}_explain")
 79→        } else {
 80→            format!("{name}_{query_name}_explain_sf{scale_factor}")
 81→        };
 82→
 83→        let result = panic::catch_unwind(|| {
 84→            insta::assert_snapshot!(snapshot_name, explain_plan);
 85→        });
 86→        if result.is_err() {
 87→            assertion_err = Some(format!("Snapshot assertion failed for {name}, {query_name}"));
 88→        }
 89→    });
 90→
 91→    if let Some(assertion_err) = assertion_err {
 92→        return Err(anyhow::anyhow!(assertion_err));
 93→    }
 94→
 95→    Ok(())
 96→}
 97→
 98→/// Sorts children of `PartitionedUnionExec` nodes in the explain plan output
 99→/// to ensure deterministic snapshot comparison.
100→///
101→/// The approach: when we find `PartitionedUnionExec`, we identify child subtrees
102→/// by their indentation level. Lines at the first child's indent level start new
103→/// subtrees. We sort all subtrees alphabetically.
104→fn sort_partitioned_union_children(explain_plan: &str) -> String {
105→    // if no PartitionedUnionExec, return unchanged
106→    if !explain_plan.contains("PartitionedUnionExec") {
107→        return explain_plan.to_string();
108→    }
109→
110→    let lines: Vec<&str> = explain_plan.lines().collect();
111→    let mut result: Vec<String> = Vec::with_capacity(lines.len());
112→
113→    let mut i = 0;
114→    while i < lines.len() {
115→        let line = lines[i];
116→        result.push(line.to_string());
117→
118→        // Check if this line contains PartitionedUnionExec
119→        if line.contains("PartitionedUnionExec") && i + 1 < lines.len() {
120→            let parent_indent = get_indent_level(line);
121→            let first_child_indent = get_indent_level(lines[i + 1]);
122→
123→            // The first child should have greater indentation
124→            if first_child_indent <= parent_indent {
125→                i += 1;
126→                continue;
127→            }
128→
129→            // Collect all lines that belong to PartitionedUnionExec children
130→            // Stop at empty-content lines (table separators) or lower indent
131→            let children_start = i + 1;
132→            let mut children_end = children_start;
133→            while children_end < lines.len() {
134→                let child_line = lines[children_end];
135→                // Stop at empty-content lines (table row separators)
136→                if is_empty_content_line(child_line) {
137→                    break;
138→                }
139→                let child_indent = get_indent_level(child_line);
140→                if child_indent <= parent_indent {
141→                    break;
142→                }
143→                children_end += 1;
144→            }
145→
146→            // Split children into subtrees based on indent level
147→            let mut subtrees: Vec<Vec<&str>> = Vec::new();
148→            let mut current_subtree: Vec<&str> = Vec::new();
149→
150→            for current_line in lines.iter().take(children_end).skip(children_start) {
151→                // A line at the first child's indent level starts a new subtree
152→                if get_indent_level(current_line) == first_child_indent
153→                    && !current_subtree.is_empty()
154→                {
155→                    subtrees.push(current_subtree);
156→                    current_subtree = Vec::new();
157→                }
158→                current_subtree.push(current_line);
159→            }
160→            if !current_subtree.is_empty() {
161→                subtrees.push(current_subtree);
162→            }
163→
164→            // Sort all subtrees by their string representation
165→            subtrees.sort_by(|a, b| {
166→                let a_str = a.join("\n");
167→                let b_str = b.join("\n");
168→                a_str.cmp(&b_str)
169→            });
170→
171→            // Add sorted subtrees to result
172→            for subtree in &subtrees {
173→                for subtree_line in subtree {
174→                    result.push((*subtree_line).to_string());
175→                }
176→            }
177→
178→            i = children_end;
179→            continue;
180→        }
181→        i += 1;
182→    }
183→
184→    result.join("\n")
185→}
186→
187→/// Checks if a line contains only whitespace and `|` characters (empty table cell).
188→fn is_empty_content_line(line: &str) -> bool {
189→    line.chars().all(|c| c.is_whitespace() || c == '|')
190→}
191→
192→/// Gets the indentation level of a line in the explain plan.
193→/// Counts leading whitespace and `|` characters before the first content.
194→fn get_indent_level(line: &str) -> usize {
195→    line.chars()
196→        .take_while(|c| c.is_whitespace() || *c == '|')
197→        .count()
198→}
