 37→async fn wait_until_true<F, Fut>(max_wait: Duration, mut f: F) -> bool
 38→where
 39→    F: FnMut() -> Fut,
 40→    Fut: Future<Output = bool>,
 41→{
 42→    let start = std::time::Instant::now();
 43→    while start.elapsed() < max_wait {
 44→        if f().await {
 45→            return true;
 46→        }
 47→        tokio::time::sleep(Duration::from_millis(100)).await;
 48→    }
 49→    false
 50→}
