102→impl StartRequest {
103→    pub fn new(spiced_path: PathBuf, spicepod: SpicepodDefinition) -> Result<Self> {
104→        Ok(Self {
105→            spiced_path,
106→            spicepod,
107→            tempdir: TempDir::new()?,
108→            prepared: false,
109→            data_dir: None,
110→            additional_args: Vec::new(),
111→        })
112→    }
