114→    #[must_use]
115→    pub fn with_data_dir(mut self, data_dir: PathBuf) -> Self {
116→        self.data_dir = Some(data_dir);
117→        self
118→    }
119→
120→    #[must_use]
121→    pub fn with_additional_args(mut self, args: Vec<String>) -> Self {
122→        self.additional_args = args;
123→        self
124→    }
125→
126→    #[must_use]
127→    pub fn get_tempdir_path(&self) -> PathBuf {
128→        self.tempdir.path().to_path_buf()
129→    }
130→
131→    pub fn prepare(&mut self) -> Result<()> {
132→        // Serialize spicepod to `spicepod.yaml` in the tempdir
133→        let spicepod_yaml = yaml::to_string(&self.spicepod)?;
134→        let spicepod_yaml_path = self.tempdir.path().join("spicepod.yaml");
135→        std::fs::write(spicepod_yaml_path, spicepod_yaml)?;
136→
137→        // Create a symlink to the data directory if one is set
138→        if let Some(data_dir) = &self.data_dir {
139→            // resolve the data directory path to an absolute path
140→            let data_dir = data_dir.canonicalize()?;
141→
142→            let data_dir_symlink = self.tempdir.path().join("data");
143→            #[cfg(not(target_os = "windows"))]
144→            {
145→                std::os::unix::fs::symlink(data_dir, data_dir_symlink)?;
146→            }
147→            #[cfg(target_os = "windows")]
148→            {
149→                std::os::windows::fs::symlink_dir(data_dir, data_dir_symlink)?;
150→            }
151→        }
152→
153→        self.prepared = true;
154→
155→        Ok(())
156→    }
157→}
