159→impl SpicedInstance {
160→    #[must_use]
161→    pub fn empty() -> Self {
162→        Self::Existing
163→    }
164→
165→    /// Create an instance that connects to an external spiced at the given Flight URL.
166→    ///
167→    /// The HTTP base URL is derived from the Flight URL by replacing the port with 8090,
168→    /// or can be explicitly provided.
169→    #[must_use]
170→    pub fn external(flight_url: impl Into<String>) -> Self {
171→        let flight_url = flight_url.into();
172→        // Derive HTTP URL from Flight URL by replacing port
173→        // e.g., "http://localhost:50051" -> "http://localhost:8090"
174→        let http_base_url = if let Some(last_colon) = flight_url.rfind(':') {
175→            format!("{}:8090", &flight_url[..last_colon])
176→        } else {
177→            format!("{flight_url}:8090")
178→        };
179→        Self::External {
180→            flight_url,
181→            http_base_url,
182→        }
183→    }
184→
185→    /// Create an instance with explicit Flight and HTTP URLs.
186→    #[must_use]
187→    pub fn external_with_http(
188→        flight_url: impl Into<String>,
189→        http_base_url: impl Into<String>,
190→    ) -> Self {
191→        Self::External {
192→            flight_url: flight_url.into(),
193→            http_base_url: http_base_url.into(),
194→        }
195→    }
196→
197→    /// Start a spiced instance
198→    ///
199→    /// # Errors
200→    ///
201→    /// - If spiced is already running
202→    /// - If the spiced instance fails to start
203→    /// - If the spicepod definition fails to serialize
204→    pub async fn start(mut start_request: StartRequest) -> Result<Self> {
205→        // Check if spiced is already running
206→        let client = reqwest::Client::new();
207→        let health_url = format!("{HTTP_BASE_URL}{HEALTH_ENDPOINT}");
208→        let response = client.get(&health_url).send().await;
209→        if response.is_ok() {
210→            anyhow::bail!("Spiced instance is already running");
211→        }
212→
213→        if !start_request.prepared {
214→            start_request.prepare()?;
215→        }
216→
217→        let tempdir = start_request.tempdir;
218→
219→        // Get spiced version
220→        let version_cmd = Command::new(start_request.spiced_path.clone())
221→            .arg("--version")
222→            .output()?;
223→
224→        if !version_cmd.status.success() {
225→            anyhow::bail!(
226→                "Failed to get spiced version: {}",
227→                String::from_utf8_lossy(&version_cmd.stderr)
228→            );
229→        }
230→
231→        let version = String::from_utf8_lossy(&version_cmd.stdout).to_string();
232→        // take just the v1.0.0 part of the version
233→        let version = match (version.contains('-'), version.contains('+')) {
234→            (true, _) => version.split('-').next().unwrap_or(&version).to_string(),
235→            (false, true) => version.split('+').next().unwrap_or(&version).to_string(),
236→            (false, false) => version,
237→        };
238→
239→        // Start the spiced instance
240→        let mut cmd = Command::new(start_request.spiced_path);
241→        cmd.current_dir(tempdir.path());
242→        cmd.arg("--telemetry-enabled=false");
243→
244→        // Add any additional arguments
245→        for arg in start_request.additional_args {
246→            cmd.arg(arg);
247→        }
248→
249→        let child = cmd.spawn()?;
250→
251→        Ok(Self::Owned {
252→            child,
253→            tempdir,
254→            version: SpicedVersion::new(version),
255→        })
256→    }
257→
258→    #[must_use]
259→    pub fn version(&self) -> &str {
260→        let Self::Owned { version, .. } = self else {
261→            return "unknown";
262→        };
263→
264→        version.0.as_str()
265→    }
266→
267→    pub fn get_tempdir_path(&self) -> Result<PathBuf> {
268→        let Self::Owned { tempdir, .. } = self else {
269→            anyhow::bail!("SpicedInstance is not owned, no tempdir available");
270→        };
271→
272→        Ok(tempdir.path().to_path_buf())
273→    }
274→
275→    /// Get a flight client for the spiced instance
276→    ///
277→    /// # Errors
278→    ///
279→    /// - If the flight client fails to be created
280→    pub async fn flight_client(
281→        &self,
282→        api_key: Option<String>,
283→        disable_caching: bool,
284→    ) -> Result<FlightClient> {
285→        let credentials = if let Some(key) = api_key {
286→            Credentials::Bearer {
287→                token: std::sync::Arc::new(SecretString::new(key.into())),
288→                prefix: true,
289→            }
290→        } else {
291→            Credentials::Anonymous
292→        };
293→
294→        let flight_url = match self {
295→            Self::External { flight_url, .. } => flight_url.as_str(),
296→            Self::Existing | Self::Owned { .. } => FLIGHT_URL,
297→        };
298→
299→        let mut metadata = tonic::metadata::MetadataMap::new();
300→        if disable_caching {
301→            metadata.insert("cache-control", "no-cache".parse()?);
302→        }
303→
304→        let flight_client = FlightClient::try_new(
305→            std::sync::Arc::from(flight_url),
306→            credentials,
307→            Some(metadata),
308→            None,
309→        )
310→        .await
311→        .map_err(|e| anyhow!("{e}"))?;
312→
313→        Ok(flight_client)
314→    }
315→
316→    /// Get an http client for the spiced instance
317→    ///
318→    /// # Errors
319→    ///
320→    /// - If the http client fails to be created
321→    pub fn http_client(&self) -> Result<reqwest::Client> {
322→        Ok(reqwest::Client::builder()
323→            .user_agent("spice-test-framework/1.0")
324→            .build()?)
325→    }
326→
327→    /// Get the HTTP base URL for this instance
328→    #[must_use]
329→    pub fn http_base_url(&self) -> &str {
330→        match self {
331→            Self::External { http_base_url, .. } => http_base_url.as_str(),
332→            Self::Existing | Self::Owned { .. } => HTTP_BASE_URL,
333→        }
334→    }
335→
336→    /// Wait for the spiced instance to be ready
337→    ///
338→    /// # Errors
339→    ///
340→    /// - If the spiced instance fails to be ready within the timeout
341→    pub async fn wait_for_ready(&mut self, timeout: Duration) -> Result<()> {
342→        // Wait for the spiced instance to be ready by polling the `/v1/ready` endpoint
343→        let client = self.http_client()?;
344→        let http_base = self.http_base_url().to_string();
345→        let ready_url = format!("{http_base}{READY_ENDPOINT}");
346→        if !wait_until_true(timeout, || async {
347→            let response = client.get(&ready_url).send().await;
348→            match response {
349→                Ok(response) => response.status().is_success(),
350→                Err(_) => false,
351→            }
352→        })
353→        .await
354→        {
355→            anyhow::bail!("Spiced instance not ready within {timeout:?}");
356→        }
357→
358→        // Give Flight server a moment to finish starting up after HTTP is ready
359→        // Flight starts asynchronously and may not be available immediately
360→        tokio::time::sleep(Duration::from_millis(500)).await;
361→
362→        Ok(())
363→    }
364→
365→    pub async fn is_ready(&self) -> bool {
366→        let Ok(client) = self.http_client() else {
367→            return false;
368→        };
369→        let ready_url = format!("{}{READY_ENDPOINT}", self.http_base_url());
370→        let response = client.get(&ready_url).send().await;
371→        match response {
372→            Ok(response) => response.status().is_success(),
373→            Err(_) => false,
374→        }
375→    }
376→
377→    /// Stop the spiced instance
378→    ///
379→    /// # Errors
380→    ///
381→    /// - If the spiced instance fails to exit
382→    pub fn stop(&mut self) -> Result<()> {
383→        let Self::Owned { child, .. } = self else {
384→            return Ok(());
385→        };
386→
387→        #[cfg(not(target_os = "windows"))]
388→        {
389→            // Send a SIGTERM to the spiced instance and wait for it to exit
390→            let Ok(pid_i32) = child.id().try_into() else {
391→                anyhow::bail!("Failed to convert pid to i32");
392→            };
393→            nix::sys::signal::kill(
394→                nix::unistd::Pid::from_raw(pid_i32),
395→                nix::sys::signal::Signal::SIGTERM,
396→            )?;
397→            child.wait()?;
398→        }
399→
400→        #[cfg(target_os = "windows")]
401→        {
402→            // On Windows, we can use the built-in process termination
403→            child.kill()?;
404→            child.wait()?;
405→        }
406→
407→        Ok(())
408→    }
409→
410→    /// Returns an instance of a `Process` for the spiced instance
411→    /// This allows tracking the spiced process, without owning the spiced instance
412→    pub fn process(&self) -> Result<Process> {
413→        let Self::Owned { child, .. } = self else {
414→            anyhow::bail!("SpicedInstance is not owned, no process available");
415→        };
416→
417→        Ok(Process::new(Pid::from_u32(child.id())))
418→    }
419→}
