421→impl Drop for SpicedInstance {
422→    fn drop(&mut self) {
423→        let Self::Owned { child, .. } = self else {
424→            return;
425→        };
426→
427→        match child.kill() {
428→            Ok(()) => (),
429→            Err(e) => eprintln!("Failed to kill spiced instance: {e}"),
430→        }
431→    }
432→}
