 40→const ENDPOINT_CONST: &str = "https://telemetry.spiceai.io";
 41→
 42→pub static ENDPOINT: LazyLock<Arc<str>> = LazyLock::new(|| {
 43→    std::env::var("SPICEAI_TELEMETRY_ENDPOINT")
 44→        .unwrap_or_else(|_| ENDPOINT_CONST.into())
 45→        .into()
 46→});
