 70→#[derive(Debug, Clone)]
 71→pub struct OtlpExporterConfig {
 72→    pub endpoint: Arc<str>,
 73→    pub headers: Vec<(String, String)>,
 74→    pub timeout: Duration,
 75→}
 76→
 77→enum TelemetryBackend {
 78→    Arrow { api_key: Option<SecretString> },
 79→    Otlp(OtlpExporterConfig),
 80→}
 81→
 82→pub struct Telemetry {
 83→    reader: InitialReader,
 84→    resource: Resource,
 85→    setup: bool,
 86→    backend: TelemetryBackend,
 87→}
 88→
 89→impl Telemetry {
 90→    /// Create telemetry with empty resource.
 91→    /// Use `set_resource()` later to set the actual resource before calling `emit()`.
 92→    #[must_use]
 93→    pub fn new(api_key_name: &str) -> Self {
 94→        let resource = Resource::builder_empty().build();
 95→        Self::new_with_resource(&resource, api_key_name)
 96→    }
 97→
 98→    /// Create telemetry with a resource provided upfront.
 99→    ///
100→    /// Use this when the resource attributes are already available at creation time.
101→    /// For most cases, prefer `new()` + `set_resource()` to ensure telemetry is initialized
102→    /// before any metrics calls.
103→    #[must_use]
104→    pub fn new_with_resource(resource: &Resource, api_key_name: &str) -> Self {
105→        let reader = InitialReader::default();
106→
107→        let provider = SdkMeterProvider::builder()
108→            .with_resource(resource.clone())
109→            .with_reader(reader.clone())
110→            .build();
111→
112→        let provider: Arc<dyn MeterProvider + Send + Sync> = Arc::new(provider);
113→        let setup = METER_PROVIDER_ONCE.set(Arc::clone(&provider)).is_ok();
114→        if !setup {
115→            println!("Telemetry disabled");
116→        }
117→
118→        // Initialize METER after the provider is set to avoid binding to a noop meter.
119→        let _ = METER.set(provider.meter("benchmarks_telemetry"));
120→
121→        let api_key = std::env::var(api_key_name)
122→            .ok()
123→            .as_deref()
124→            .map(|key| SecretString::new(key.into()));
125→
126→        Self {
127→            reader,
128→            resource: resource.clone(),
129→            setup,
130→            backend: TelemetryBackend::Arrow { api_key },
131→        }
132→    }
133→
134→    #[must_use]
135→    pub fn with_otlp(config: OtlpExporterConfig) -> Self {
136→        let resource = Resource::builder_empty().build();
137→        Self::with_otlp_resource(config, resource)
138→    }
139→
140→    /// Create telemetry with OTLP backend and a resource provided upfront.
141→    ///
142→    /// Use this when the resource attributes are already available at creation time.
143→    #[must_use]
144→    pub fn with_otlp_resource(config: OtlpExporterConfig, resource: Resource) -> Self {
145→        let reader = InitialReader::default();
146→
147→        let provider = SdkMeterProvider::builder()
148→            .with_resource(resource.clone())
149→            .with_reader(reader.clone())
150→            .build();
151→
152→        let provider: Arc<dyn MeterProvider + Send + Sync> = Arc::new(provider);
153→        let setup = METER_PROVIDER_ONCE.set(Arc::clone(&provider)).is_ok();
154→        if !setup {
155→            println!("Telemetry disabled");
156→        }
157→
158→        // Initialize METER after the provider is set to avoid binding to a noop meter.
159→        let _ = METER.set(provider.meter("benchmarks_telemetry"));
160→
161→        Self {
162→            reader,
163→            resource,
164→            setup,
165→            backend: TelemetryBackend::Otlp(config),
166→        }
167→    }
168→
169→    /// Set the resource to be used when emitting metrics.
170→    ///
171→    /// Call this after collecting all the resource attributes (e.g., `spiced_version`, `commit_sha`)
172→    /// but before calling `emit()`.
173→    pub fn set_resource(&mut self, resource: Resource) {
174→        self.resource = resource;
175→    }
176→
177→    pub async fn emit(&self) -> Result<()> {
178→        if !self.setup {
179→            return Ok(());
180→        }
181→
182→        match &self.backend {
183→            TelemetryBackend::Arrow { api_key } => {
184→                if let Some(api_key) = api_key {
185→                    println!("Emitting to exporter at {}", *ENDPOINT);
186→                    let telemetry_exporter = otel_arrow::OtelArrowExporter::new(
187→                        TelemetryExporterBuilder::new()
188→                            .with_credentials(flight_client::Credentials::Bearer {
189→                                token: api_key.clone().into(),
190→                                prefix: false,
191→                            })
192→                            .with_service_name("benchmarks_telemetry".into())
193→                            .with_endpoint(Arc::clone(&ENDPOINT))
194→                            .build()
195→                            .await?,
196→                    );
197→
198→                    let mut rm = ResourceMetrics::default();
199→
200→                    self.reader.collect(&mut rm)?;
201→
202→                    // Note: In OpenTelemetry SDK 0.31+, ResourceMetrics.resource is set by the
203→                    // pipeline during collection and cannot be overridden.
204→
205→                    telemetry_exporter.export(&rm).await.unwrap_or_else(|err| {
206→                        println!("Failed to export initial telemetry: {err:?}");
207→                    });
208→                } else {
209→                    println!("No API key provided, telemetry is disabled");
210→                }
211→            }
212→            TelemetryBackend::Otlp(config) => {
213→                let mut rm = ResourceMetrics::default();
214→                // Note: Resource is set by the pipeline during collection.
215→                self.reader.collect(&mut rm)?;
216→
217→                let exporter = MetricExporter::builder()
218→                    .with_tonic()
219→                    .with_timeout(config.timeout)
220→                    .with_endpoint(config.endpoint.as_ref())
221→                    .build()?;
222→                exporter
223→                    .export(&rm)
224→                    .await
225→                    .unwrap_or_else(|err| println!("Failed to export OTLP telemetry: {err:?}"));
226→            }
227→        }
228→
229→        Ok(())
230→    }
231→}
