 17→//! Streaming OTLP metrics exporter for real-time query metrics.
 18→//!
 19→//! This module provides incremental metrics export during test execution,
 20→//! allowing correlation with other system metrics in real-time.
 21→
 22→use std::sync::Arc;
 23→use std::time::Duration;
 24→
 25→use opentelemetry::metrics::{Histogram, Meter, MeterProvider as _};
 26→use opentelemetry::{KeyValue, global};
 27→use opentelemetry_otlp::{MetricExporter, WithExportConfig};
 28→use opentelemetry_sdk::Resource;
 29→use opentelemetry_sdk::metrics::{PeriodicReader, SdkMeterProvider};
 30→use tokio::sync::mpsc;
 31→use tokio::task::JoinHandle;
 32→use tokio_util::sync::CancellationToken;
 33→
 34→/// A query metric event to be exported
 35→#[derive(Debug, Clone)]
 36→pub struct QueryMetricEvent {
 37→    pub query_name: Arc<str>,
 38→    pub duration_ms: f64,
 39→    pub success: bool,
 40→    pub worker_id: usize,
 41→    /// Reason for failure, if any (e.g., "error", "timeout")
 42→    pub failure_reason: Option<String>,
 43→}
 44→
 45→impl QueryMetricEvent {
 46→    /// Create a new query metric event
 47→    #[must_use]
 48→    pub fn new(query_name: String, duration: Duration, success: bool, worker_id: usize) -> Self {
 49→        Self {
 50→            query_name: Arc::from(query_name),
 51→            duration_ms: duration.as_secs_f64() * 1000.0,
 52→            success,
 53→            worker_id,
 54→            failure_reason: None,
 55→        }
 56→    }
 57→
 58→    /// Create a new query metric event with a failure reason
 59→    #[must_use]
 60→    pub fn with_failure(
 61→        query_name: String,
 62→        duration: Duration,
 63→        worker_id: usize,
 64→        reason: impl Into<String>,
 65→    ) -> Self {
 66→        Self {
 67→            query_name: Arc::from(query_name),
 68→            duration_ms: duration.as_secs_f64() * 1000.0,
 69→            success: false,
 70→            worker_id,
 71→            failure_reason: Some(reason.into()),
 72→        }
 73→    }
 74→}
 75→
 76→/// Streaming OTLP exporter that sends query metrics in real-time
 77→pub struct StreamingOtlpExporter {
 78→    tx: mpsc::Sender<QueryMetricEvent>,
 79→    handle: JoinHandle<()>,
 80→    shutdown_token: CancellationToken,
 81→}
 82→
 83→impl StreamingOtlpExporter {
 84→    /// Spawn a new streaming OTLP exporter with the given endpoint.
 85→    ///
 86→    /// Metrics will be exported periodically (every 5 seconds).
 87→    #[must_use]
 88→    pub fn spawn(endpoint: String) -> Self {
 89→        // Use a bounded channel to avoid unbounded memory growth
 90→        let (tx, rx) = mpsc::channel(10_000);
 91→        let shutdown_token = CancellationToken::new();
 92→
 93→        let handle = tokio::spawn(Self::exporter_task(rx, endpoint, shutdown_token.clone()));
 94→
 95→        Self {
 96→            tx,
 97→            handle,
 98→            shutdown_token,
 99→        }
100→    }
101→
102→    /// Get a sender that can be cloned and passed to workers
103→    #[must_use]
104→    pub fn sender(&self) -> mpsc::Sender<QueryMetricEvent> {
105→        self.tx.clone()
106→    }
107→
108→    async fn exporter_task(
109→        mut rx: mpsc::Receiver<QueryMetricEvent>,
110→        endpoint: String,
111→        shutdown_token: CancellationToken,
112→    ) {
113→        // Build the OTLP exporter
114→        let exporter = match MetricExporter::builder()
115→            .with_tonic()
116→            .with_timeout(Duration::from_secs(10))
117→            .with_endpoint(&endpoint)
118→            .build()
119→        {
120→            Ok(exp) => exp,
121→            Err(e) => {
122→                eprintln!("Failed to create streaming OTLP exporter: {e}");
123→                return;
124→            }
125→        };
126→
127→        // Create a periodic reader that exports every 5 seconds
128→        let reader = PeriodicReader::builder(exporter)
129→            .with_interval(Duration::from_secs(5))
130→            .build();
131→
132→        let resource = Resource::builder()
133→            .with_service_name("spicebench-streaming")
134→            .build();
135→
136→        let provider = SdkMeterProvider::builder()
137→            .with_resource(resource)
138→            .with_reader(reader)
139→            .build();
140→
141→        // Set as global provider for this task
142→        global::set_meter_provider(provider.clone());
143→
144→        let meter: Meter = provider.meter("spicebench-streaming");
145→        let query_duration_histogram: Histogram<f64> = meter
146→            .f64_histogram("spicebench.streaming.query.duration_ms")
147→            .with_description("Query execution duration in milliseconds (streaming)")
148→            .with_unit("ms")
149→            .build();
150→
151→        let query_count = meter
152→            .u64_counter("spicebench.streaming.query.count")
153→            .with_description("Total number of queries executed (streaming)")
154→            .build();
155→
156→        let query_success_count = meter
157→            .u64_counter("spicebench.streaming.query.success_count")
158→            .with_description("Number of successful queries (streaming)")
159→            .build();
160→
161→        let query_failure_count = meter
162→            .u64_counter("spicebench.streaming.query.failure_count")
163→            .with_description("Number of failed queries (streaming)")
164→            .build();
165→
166→        println!("Streaming OTLP metrics exporter started (endpoint: {endpoint})");
167→
168→        loop {
169→            tokio::select! {
170→                Some(event) = rx.recv() => {
171→                    let mut attributes = vec![
172→                        KeyValue::new("query_name", event.query_name.to_string()),
173→                        KeyValue::new("worker_id", event.worker_id.to_string()),
174→                        KeyValue::new("success", event.success.to_string()),
175→                    ];
176→                    if let Some(reason) = &event.failure_reason {
177→                        attributes.push(KeyValue::new("failure_reason", reason.clone()));
178→                    }
179→
180→                    query_duration_histogram.record(event.duration_ms, &attributes);
181→                    query_count.add(1, &attributes);
182→
183→                    if event.success {
184→                        query_success_count.add(1, &attributes);
185→                    } else {
186→                        query_failure_count.add(1, &attributes);
187→                    }
188→                }
189→                () = shutdown_token.cancelled() => {
190→                    println!("Streaming OTLP metrics exporter shutting down");
191→                    // Drain any remaining events
192→                    while let Ok(event) = rx.try_recv() {
193→                        let mut attributes = vec![
194→                            KeyValue::new("query_name", event.query_name.to_string()),
195→                            KeyValue::new("worker_id", event.worker_id.to_string()),
196→                            KeyValue::new("success", event.success.to_string()),
197→                        ];
198→                        if let Some(reason) = &event.failure_reason {
199→                            attributes.push(KeyValue::new("failure_reason", reason.clone()));
200→                        }
201→                        query_duration_histogram.record(event.duration_ms, &attributes);
202→                        query_count.add(1, &attributes);
203→                        if event.success {
204→                            query_success_count.add(1, &attributes);
205→                        } else {
206→                            query_failure_count.add(1, &attributes);
207→                        }
208→                    }
209→
210→                    // Force a final flush
211→                    if let Err(e) = provider.force_flush() {
212→                        eprintln!("Failed to flush streaming metrics: {e}");
213→                    }
214→                    break;
215→                }
216→            }
217→        }
218→    }
219→
220→    /// Shutdown the exporter and wait for the background task to complete
221→    pub async fn shutdown(self) {
222→        self.shutdown_token.cancel();
223→        let _ = self.handle.await;
224→    }
225→}
