223→impl SpiceTest<NotStarted> {
224→    fn get_new_progress_bar(&self) -> ProgressBar {
225→        match self.state.end_condition {
226→            EndCondition::Duration(duration) => {
227→                // refresh the progress bar every 10 seconds, or every 1/1000th of the duration
228→                // for an 8 hour test, this would be every ~28 seconds
229→                ProgressBar::new((duration.as_secs() / self.state.query_set.len() as u64) * 2)
230→                // this isn't 100% representative of the progress bar count, but it's close enough (2s per query)
231→            }
232→            EndCondition::QuerySetCompleted(count) => {
233→                ProgressBar::new((self.state.query_set.len() * count) as u64)
234→            }
235→            EndCondition::Unlimited => {
236→                // For unlimited tests, use a spinner-style progress bar
237→                ProgressBar::new_spinner()
238→            }
239→        }
240→    }
241→
242→    pub fn start(mut self) -> Result<SpiceTest<Running>> {
243→        if self.state.query_set.is_empty() {
244→            return Err(anyhow::anyhow!("Query set is empty"));
245→        }
246→
247→        if self.state.parallel_count == 0 {
248→            return Err(anyhow::anyhow!("Parallel count must be greater than 0"));
249→        }
250→
251→        // Ensure executor is configured
252→        let executor = self
253→            .state
254→            .query_executor
255→            .take()
256→            .ok_or_else(|| anyhow::anyhow!("Query executor not configured"))?;
257→
258→        let multi = if self.use_progress_bars {
259→            Some(MultiProgress::new())
260→        } else {
261→            None
262→        };
263→
264→        let shutdown_token = tokio_util::sync::CancellationToken::new();
265→
266→        let row_count_validation_skip_queries: Vec<String> = self
267→            .state
268→            .query_set_type
269→            .as_ref()
270→            .map(|qs| {
271→                qs.get_row_count_validation_skip_queries(
272→                    self.state.query_overrides,
273→                    self.state.scale_factor,
274→                )
275→                .into_iter()
276→                .map(String::from)
277→                .collect()
278→            })
279→            .unwrap_or_default();
280→
281→        let mut query_workers = Vec::new();
282→        for id in 0..self.state.parallel_count {
283→            let mut worker = SpiceTestQueryWorker::new(
284→                id,
285→                self.state.query_set.clone(),
286→                self.state.end_condition,
287→                self.name.clone(),
288→                executor.clone(),
289→            )
290→            .with_explain_plan_snapshot(self.explain_plan_snapshot)
291→            .with_results_snapshot(self.results_snapshot_predicate)
292→            .with_validate(self.state.validate)
293→            .with_scale_factor(self.state.scale_factor)
294→            .with_shutdown_token(shutdown_token.clone())
295→            .with_skip_row_count_validation(row_count_validation_skip_queries.clone());
296→
297→            if let Some(multi) = &multi {
298→                worker = worker.with_progress_bar(multi.add(self.get_new_progress_bar()));
299→            }
300→
301→            if let Some(validation_data) = &self.state.validation_data {
302→                worker = worker.with_validation_data(validation_data.clone());
303→            }
304→
305→            if let Some(reference_schema) = &self.state.reference_schema {
306→                worker = worker.with_reference_schema(Some(reference_schema.clone()));
307→            }
308→
309→            if let Some(sender) = &self.state.streaming_metrics_sender {
310→                worker = worker.with_streaming_metrics(sender.clone());
311→            }
312→
313→            if let Some(threshold) = self.state.query_duration_threshold {
314→                worker = worker.with_query_duration_threshold(threshold);
315→            }
316→
317→            query_workers.push(worker.start());
318→        }
319→
320→        Ok(SpiceTest {
321→            name: self.name,
322→            spiced_instance: self.spiced_instance,
323→            start_time: self.start_time,
324→            use_progress_bars: self.use_progress_bars,
325→            api_key: self.api_key,
326→            explain_plan_snapshot: self.explain_plan_snapshot,
327→            results_snapshot_predicate: self.results_snapshot_predicate,
328→            state: Running {
329→                start_time: Instant::now(),
330→                query_workers,
331→                progress_bar: multi,
332→                query_count: self.state.query_count,
333→                parallel_count: self.state.parallel_count,
334→                end_condition: self.state.end_condition,
335→                shutdown_token,
336→            },
337→        })
338→    }
339→}
