341→impl SpiceTest<Running> {
342→    #[must_use]
343→    pub fn cancellation_token(&self) -> tokio_util::sync::CancellationToken {
344→        self.state.shutdown_token.clone()
345→    }
346→
347→    pub fn cancel(&self) {
348→        self.state.shutdown_token.cancel();
349→    }
350→
351→    pub async fn wait(self) -> Result<SpiceTest<Completed>> {
352→        let mut query_durations = BTreeMap::new();
353→        let mut query_iteration_durations = BTreeMap::new();
354→        let mut row_counts = BTreeMap::new();
355→        let mut query_statuses = BTreeMap::new();
356→        for worker_result in join_all(self.state.query_workers).await {
357→            let worker_result = worker_result??;
358→            if worker_result.connection_failed {
359→                return Err(anyhow::anyhow!(
360→                    "Test failed - a connection failed during the test"
361→                ));
362→            }
363→
364→            for (query, duration) in worker_result.query_durations {
365→                query_durations
366→                    .entry(query)
367→                    .or_insert_with(Vec::new)
368→                    .extend(duration);
369→            }
370→
371→            for (query, iteration_durations) in worker_result.query_iteration_durations {
372→                query_iteration_durations
373→                    .entry(query)
374→                    .or_insert_with(|| iteration_durations);
375→            }
376→
377→            for (query, query_row_counts) in worker_result.row_counts {
378→                row_counts
379→                    .entry(query)
380→                    .or_insert_with(Vec::new)
381→                    .extend(query_row_counts);
382→            }
383→
384→            for (query, worker_status) in worker_result.query_statuses {
385→                query_statuses
386→                    .entry(query)
387→                    .and_modify(|existing_status| {
388→                        // If the worker reports failure, update the status to Failed
389→                        if matches!(existing_status, QueryStatus::Failed(_)) {
390→                            return; // don't update any existing status message
391→                        }
392→
393→                        if matches!(worker_status, QueryStatus::Failed(_)) {
394→                            *existing_status = worker_status.clone();
395→                        }
396→                    })
397→                    .or_insert(worker_status);
398→            }
399→        }
400→
401→        if let Some(multi) = self.state.progress_bar {
402→            multi.clear()?;
403→        }
404→
405→        Ok(SpiceTest {
406→            name: self.name,
407→            spiced_instance: self.spiced_instance,
408→            start_time: self.start_time,
409→            use_progress_bars: self.use_progress_bars,
410→            api_key: self.api_key,
411→            explain_plan_snapshot: self.explain_plan_snapshot,
412→            results_snapshot_predicate: self.results_snapshot_predicate,
413→            state: Completed {
414→                query_durations,
415→                query_iteration_durations,
416→                row_counts,
417→                query_statuses,
418→                test_duration: self.state.start_time.elapsed(),
419→                end_time: SystemTime::now(),
420→                query_count: self.state.query_count,
421→                parallel_count: self.state.parallel_count,
422→                end_condition: self.state.end_condition,
423→            },
424→        })
425→    }
426→}
