428→impl SpiceTest<Completed> {
429→    #[must_use]
430→    pub fn get_query_durations(&self) -> &BTreeMap<Arc<str>, Vec<Duration>> {
431→        &self.state.query_durations
432→    }
433→
434→    /// Returns the start and end time of for all consecutive query iterations of the same query in a set.
435→    ///
436→    /// Only valid when the `EndCondition` is `QuerySetCompleted`.
437→    #[must_use]
438→    pub fn get_query_iteration_durations(&self) -> &BTreeMap<Arc<str>, (SystemTime, SystemTime)> {
439→        &self.state.query_iteration_durations
440→    }
441→
442→    #[must_use]
443→    pub fn get_cumulative_query_duration(&self) -> Duration {
444→        self.state.query_durations.values().flatten().copied().sum()
445→    }
446→
447→    #[must_use]
448→    pub fn get_test_duration(&self) -> Duration {
449→        self.state.test_duration
450→    }
451→
452→    pub fn get_throughput_metric(&self, scale: f64) -> Result<f64> {
453→        // metric = (Parallel Query Count * Test Suite Query Count * 3600) / Cs * Scale
454→        let lhs = self.state.parallel_count * self.state.query_count * 3600;
455→
456→        // u32 is safe because lhs is unlikely to be greater than u32::MAX unless some extreme parameters are used (more than 1000 parallel and query count)
457→        let lhs = f64::from(u32::try_from(lhs)?);
458→
459→        // because we perform query sets one after the other, we're not 100% like the original TPCH QpH metric because it expects to only run once
460→        // apply a modifier based on the query set count
461→        // e.g. query set count of 5, means our calculated QpH needs to be times 5 because we ran 5 query sets
462→        // this adjusts for a longer test duration as a result of running multiple query sets, which would otherwise reduce the QpH
463→        let end_condition_modifier = match self.state.end_condition {
464→            EndCondition::Duration(_) => {
465→                return Err(anyhow::anyhow!(
466→                    "Throughput metric calculation for duration-based tests is not supported. Use a QuerySetCompleted test instead."
467→                ));
468→            }
469→            EndCondition::Unlimited => {
470→                return Err(anyhow::anyhow!(
471→                    "Throughput metric calculation is not supported for unlimited tests."
472→                ));
473→            }
474→            EndCondition::QuerySetCompleted(count) => f64::from(u32::try_from(count)?),
475→        };
476→
477→        Ok((lhs / self.state.test_duration.as_secs_f64()) * scale * end_condition_modifier)
478→    }
479→
480→    /// Validates that row counts are consistent across queries
481→    /// Each query should return the same number of rows
482→    pub fn validate_returned_row_counts(&self) -> Result<BTreeMap<Arc<str>, usize>> {
483→        // validate that row counts are consistent across queries - each query should return the same number of rows
484→        let mut returned_row_counts = BTreeMap::new();
485→        for (query, counts) in &self.state.row_counts {
486→            let first = counts
487→                .first()
488→                .ok_or_else(|| anyhow::anyhow!("No row counts found for query {query}"))?;
489→            if !counts.iter().all(|count| count == first) {
490→                return Err(anyhow::anyhow!(
491→                    "Row counts for query {query} are inconsistent"
492→                ));
493→            }
494→
495→            returned_row_counts.insert(Arc::clone(query), *first);
496→        }
497→
498→        Ok(returned_row_counts)
499→    }
500→
501→    /// Returns true if every query status is passed. Returns false if any query status is failed.
502→    #[must_use]
503→    pub fn succeeded(&self) -> bool {
504→        self.state
505→            .query_statuses
506→            .values()
507→            .all(|status| status == &QueryStatus::Passed)
508→    }
509→}
