523→impl MetricCollector<DatasetMetrics, NoExtendedMetrics> for SpiceTest<Completed> {
524→    fn start_time(&self) -> SystemTime {
525→        self.start_time
526→    }
527→
528→    fn end_time(&self) -> SystemTime {
529→        self.state.end_time
530→    }
531→
532→    fn name(&self) -> String {
533→        self.name.clone()
534→    }
535→
536→    fn spiced_version(&self) -> Result<&str> {
537→        Ok(self
538→            .spiced_instance
539→            .as_ref()
540→            .map(|i| i.version())
541→            .unwrap_or("unknown"))
542→    }
543→
544→    fn metrics(&self) -> Result<Vec<QueryMetric<DatasetMetrics>>> {
545→        self.get_query_durations()
546→            .iter()
547→            .map(|(query, durations)| {
548→                let query_iteration_durations = self.state.query_iteration_durations.get(query);
549→                let query_start_time =
550→                    query_iteration_durations.map_or(self.start_time, |(start, _)| *start);
551→                let query_end_time =
552→                    query_iteration_durations.map_or(self.state.end_time, |(_, end)| *end);
553→                let query_status = self
554→                    .state
555→                    .query_statuses
556→                    .get(query)
557→                    .unwrap_or(&QueryStatus::Failed(None))
558→                    .to_owned();
559→
560→                let metric = QueryMetric::new_from_durations(
561→                    Arc::clone(query),
562→                    durations,
563→                    query_status,
564→                    system_time_to_unix_epoch_ms(query_start_time)?,
565→                    system_time_to_unix_epoch_ms(query_end_time)?,
566→                );
567→
568→                metric.map(|metric| {
569→                    metric.with_extended_metrics(DatasetMetrics::new(self.name.clone()))
570→                })
571→            })
572→            .collect::<Result<Vec<_>>>()
573→    }
574→}
