196→    /// Send a query metric event to the streaming exporter if configured.
197→    /// If a duration threshold is set and the query exceeds it, it will be marked as a timeout failure.
198→    fn send_streaming_metric(&self, query_name: &str, duration: Duration, success: bool) {
199→        let Some(sender) = &self.streaming_metrics_sender else {
200→            return;
201→        };
202→
203→        // Check if duration exceeds threshold - if so, mark as timeout failure
204→        let exceeded_threshold =
205→            success && self.query_duration_threshold.is_some_and(|t| duration > t);
206→
207→        let event = if exceeded_threshold {
208→            QueryMetricEvent::with_failure(query_name.to_string(), duration, self.id, "timeout")
209→        } else if success {
210→            QueryMetricEvent::new(query_name.to_string(), duration, true, self.id)
211→        } else {
212→            QueryMetricEvent::with_failure(query_name.to_string(), duration, self.id, "error")
213→        };
214→
215→        // Non-blocking send - if channel is full, we drop the metric
216→        let _ = sender.try_send(event);
217→    }
