219→    /// Validate query results against expected data
220→    /// Uses TPCH validation for TPCH queries, custom validation data for scenario queries
221→    fn validate_query_results(
222→        &self,
223→        query: &Query,
224→        actual_batches: &[RecordBatch],
225→    ) -> Result<QueryValidationResult> {
226→        // Check if we have custom validation data for this query
227→        if let Some(validation_data) = &self.validation_data
228→            && let Some(expected_batches) = validation_data.get(&query.name)
229→        {
230→            return validation::validate_with_expected_batches(
231→                &query.name,
232→                actual_batches,
233→                expected_batches,
234→            );
235→        }
236→
237→        // Fall back to TPCH validation (which handles TPCH, parameterized TPCH, etc.)
238→        validation::validate_tpch_query(query, actual_batches)
239→    }
