241→    pub fn start(self) -> JoinHandle<Result<SpiceTestQueryWorkerResult>> {
242→        tokio::spawn(async move {
243→            // Load test queries may be generated with multiple parameter sets, resulting in a large
244→            // set of queries. To respect duration limits, we group queries by name and run one
245→            // group at a time, cycling through each group's parameter variations.
246→            // If queries are unique, it will result in a single query set and will be the same as usual
247→            let query_sets = build_unique_query_sets(&self.query_set)?;
248→
249→            let query_durations: Arc<DashMap<Arc<str>, Vec<Duration>>> = Arc::new(DashMap::new());
250→
251→            // Keeps track of the start and end time of each query iteration
252→            let mut query_iteration_durations: BTreeMap<Arc<str>, (SystemTime, SystemTime)> =
253→                BTreeMap::new();
254→
255→            let mut query_statuses: BTreeMap<Arc<str>, QueryStatus> = BTreeMap::new();
256→            let mut row_counts: BTreeMap<Arc<str>, Vec<usize>> = BTreeMap::new();
257→            let mut query_set_count = 0;
258→            let start = Instant::now();
259→
260→            match self.end_condition {
261→                EndCondition::Duration(_) | EndCondition::Unlimited => {
262→                    // For Duration-based or Unlimited end condition, keep running queries in sequence
263→                    while !self.shutdown_token.is_cancelled()
264→                        && !self.end_condition.is_met(&start, query_set_count)
265→                    {
266→                        if self.progress_bar.is_none() && self.id == 0 {
267→                            println!(
268→                                "Worker {} - Query set count: {} - Elapsed time: {:?}",
269→                                self.id,
270→                                query_set_count,
271→                                start.elapsed()
272→                            );
273→                        }
274→
275→                        // Select the query set to use for this iteration
276→                        let queries_to_run = {
277→                            let set_index = query_set_count % query_sets.len();
278→                            &query_sets[set_index]
279→                        };
280→
281→                        if !self
282→                            .run_query_set(
283→                                Arc::clone(&query_durations),
284→                                &mut query_statuses,
285→                                &mut row_counts,
286→                                queries_to_run,
287→                            )
288→                            .await?
289→                        {
290→                            return Ok(SpiceTestQueryWorkerResult::new(
291→                                &query_durations,
292→                                query_iteration_durations,
293→                                query_statuses,
294→                                true,
295→                                row_counts,
296→                            ));
297→                        }
298→                        query_set_count += 1;
299→                    }
300→                }
301→                EndCondition::QuerySetCompleted(target_count) => {
302→                    // For QuerySetCompleted, run each query target_count times before moving to next
303→                    let start = SystemTime::now();
304→                    for query in &self.query_set {
305→                        if self.shutdown_token.is_cancelled() {
306→                            break;
307→                        }
308→                        if self.validate && query.name.contains("simple") {
309→                            continue; // skip validation for simple TPCH queries, because they are not part of the spec
310→                        }
311→
312→                        let mut current_query_count = 0;
313→                        let query_start = SystemTime::now();
314→                        let mut query_status = QueryStatus::Passed;
315→
316→                        let snapshot_results = self
317→                            .results_snapshot_predicate
318→                            .is_some_and(|predicate| predicate(&query.name))
319→                            && self.id == 0; // only one worker should snapshot results
320→
321→                        // Additional round of query run before recording results.
322→                        // To discard the abnormal results caused by: establishing initial connection / spark cluster startup time
323→
324→                        let QueryRunResult {
325→                            connection_failed, ..
326→                        } = self
327→                            .run_single_query(
328→                                query,
329→                                Arc::new(DashMap::new()),
330→                                &mut BTreeMap::new(),
331→                                snapshot_results,
332→                                false,
333→                            )
334→                            .await?;
335→                        if connection_failed {
336→                            return Ok(SpiceTestQueryWorkerResult::new(
337→                                &query_durations,
338→                                query_iteration_durations,
339→                                query_statuses,
340→                                true,
341→                                row_counts,
342→                            ));
343→                        }
344→
345→                        if self.explain_plan_snapshot
346→                            && self.id == 0
347→                            && let Some(client) = self.executor.as_flight_client()
348→                        {
349→                            println!("Worker {} - Query '{}' - Explain plan", self.id, query.name);
350→                            if let Err(e) = record_explain_plan(
351→                                client,
352→                                self.name.as_str(),
353→                                query,
354→                                self.scale_factor,
355→                            )
356→                            .await
357→                            {
358→                                println!(
359→                                    "Worker {} - Query '{}' explain plan failed: {}",
360→                                    self.id, query.name, e
361→                                );
362→
363→                                query_status = QueryStatus::Failed(Some(
364→                                    "Explain plan snapshot assertion failed".into(),
365→                                ));
366→                            }
367→                        }
368→
369→                        while current_query_count < target_count {
370→                            if self.progress_bar.is_none()
371→                                && self.id == 0
372→                                && (current_query_count % 10 == 0 || target_count <= 5)
373→                            {
374→                                println!(
375→                                    "Worker {} - Query '{}' - {}/{} - Elapsed time: {:?}",
376→                                    self.id,
377→                                    query.name,
378→                                    current_query_count + 1,
379→                                    target_count,
380→                                    start.elapsed().unwrap_or_default()
381→                                );
382→                            }
383→
384→                            let QueryRunResult {
385→                                connection_failed,
386→                                query_failure,
387→                            } = self
388→                                .run_single_query(
389→                                    query,
390→                                    Arc::clone(&query_durations),
391→                                    &mut row_counts,
392→                                    false, // don't attempt to snapshot results more than once
393→                                    self.validate,
394→                                )
395→                                .await?;
396→
397→                            if connection_failed {
398→                                return Ok(SpiceTestQueryWorkerResult::new(
399→                                    &query_durations,
400→                                    query_iteration_durations,
401→                                    query_statuses,
402→                                    true,
403→                                    row_counts,
404→                                ));
405→                            }
406→
407→                            if let Some(query_failure) = query_failure {
408→                                query_status = QueryStatus::Failed(Some(query_failure.into()));
409→                            }
410→
411→                            current_query_count += 1;
412→                        }
413→                        let end = SystemTime::now();
414→                        query_iteration_durations
415→                            .insert(Arc::clone(&query.name), (query_start, end));
416→                        query_statuses.insert(Arc::clone(&query.name), query_status);
417→                    }
418→                }
419→            }
420→
421→            Ok(SpiceTestQueryWorkerResult::new(
422→                &query_durations,
423→                query_iteration_durations,
424→                query_statuses,
425→                false,
426→                row_counts,
427→            ))
428→        })
429→    }
