431→    // run queries as a duration-based test
432→    async fn run_query_set(
433→        &self,
434→        query_durations: Arc<DashMap<Arc<str>, Vec<Duration>>>,
435→        query_statuses: &mut BTreeMap<Arc<str>, QueryStatus>,
436→        row_counts: &mut BTreeMap<Arc<str>, Vec<usize>>,
437→        queries: &[Query],
438→    ) -> Result<bool> {
439→        for query in queries {
440→            let QueryRunResult {
441→                connection_failed,
442→                query_failure,
443→            } = self
444→                .run_single_query(
445→                    query,
446→                    Arc::clone(&query_durations),
447→                    row_counts,
448→                    false,
449→                    false,
450→                )
451→                .await?;
452→            if connection_failed {
453→                return Ok(false);
454→            }
455→
456→            let worker_status = if let Some(query_failure) = query_failure {
457→                QueryStatus::Failed(Some(query_failure.into()))
458→            } else {
459→                QueryStatus::Passed
460→            };
461→
462→            query_statuses
463→                .entry(Arc::clone(&query.name))
464→                .and_modify(|existing_status| {
465→                    // If the worker reports failure, update the status to Failed
466→                    if matches!(worker_status, QueryStatus::Failed(_)) {
467→                        *existing_status = worker_status.clone();
468→                    }
469→                })
470→                .or_insert(worker_status);
471→        }
472→        Ok(true)
473→    }
