475→    // run queries as a set-completion based test
476→    async fn run_single_query(
477→        &self,
478→        query: &Query,
479→        query_durations: Arc<DashMap<Arc<str>, Vec<Duration>>>,
480→        row_counts: &mut BTreeMap<Arc<str>, Vec<usize>>,
481→        results_snapshot: bool,
482→        validate: bool,
483→    ) -> Result<QueryRunResult> {
484→        match self
485→            .execute_query(
486→                query,
487→                Arc::clone(&query_durations),
488→                row_counts,
489→                results_snapshot,
490→                validate,
491→            )
492→            .await
493→        {
494→            Ok(()) => Ok(QueryRunResult {
495→                connection_failed: false,
496→                query_failure: None,
497→            }),
498→            Err(e) => {
499→                // Check if this is a connection error using typed error checking
500→                // This is more reliable than string matching
501→                let is_connection_error =
502→                    e.downcast_ref::<flight_client::Error>()
503→                        .is_some_and(|flight_err| {
504→                            matches!(
505→                                flight_err,
506→                                flight_client::Error::UnableToConnectToServer { .. }
507→                                    | flight_client::Error::UnableToPerformHandshake { .. }
508→                            )
509→                        });
510→
511→                if is_connection_error {
512→                    eprintln!(
513→                        "FAIL - EARLY EXIT - Worker {} - Query '{}' failed: {}",
514→                        self.id, query.name, e
515→                    );
516→                    Ok(QueryRunResult {
517→                        connection_failed: true,
518→                        query_failure: None,
519→                    })
520→                } else {
521→                    eprintln!(
522→                        "{} FAIL - Worker {} - Query '{}' failed: {}",
523→                        chrono::Utc::now(),
524→                        self.id,
525→                        query.name,
526→                        e
527→                    );
528→
529→                    query_durations.entry(Arc::clone(&query.name)).or_default();
530→                    Ok(QueryRunResult {
531→                        connection_failed: false,
532→                        query_failure: Some(format!("{e}")),
533→                    })
534→                }
535→            }
536→        }
537→    }
