539→    async fn execute_query(
540→        &self,
541→        query: &Query,
542→        query_durations: Arc<DashMap<Arc<str>, Vec<Duration>>>,
543→        row_counts: &mut BTreeMap<Arc<str>, Vec<usize>>,
544→        results_snapshot: bool,
545→        validate: bool,
546→    ) -> Result<()> {
547→        // Execute query using the configured executor
548→        let result = self.executor.execute(query).await?;
549→
550→        // Handle validation if supported and requested
551→        if validate
552→            && self.executor.supports_validation()
553→            && let Some(batches) = &result.batches
554→        {
555→            // Execute reference query if reference_schema is provided
556→            if let Some(ref_schema) = &self.reference_schema
557→                && let Some(flight_client) = self.executor.as_flight_client()
558→            {
559→                let reference_query = query.rewrite_with_reference_schema(ref_schema)?;
560→                println!(
561→                    "Worker {} - Query '{}' - Executing reference query against {}.* tables",
562→                    self.id, query.name, ref_schema
563→                );
564→
565→                let mut ref_result_stream = flight_client
566→                    .query(reference_query.to_sql_with_inlined_params().as_ref())
567→                    .await?;
568→
569→                let mut ref_batches = vec![];
570→                while let Some(batch) = ref_result_stream.try_next().await? {
571→                    ref_batches.push(batch);
572→                }
573→
574→                // Validate against reference query results
575→                let validation_result =
576→                    validation::validate_with_expected_batches(&query.name, batches, &ref_batches)?;
577→
578→                if let QueryValidationResult::Fail(validation_reason) = validation_result {
579→                    eprintln!(
580→                        "\n{} FAIL - Worker {} - Query '{}' reference validation failed",
581→                        chrono::Utc::now(),
582→                        self.id,
583→                        query.name
584→                    );
585→                    eprintln!("Query SQL: {}", query.sql);
586→                    eprintln!("Validation failure reason: {validation_reason:?}");
587→                    eprintln!("\nExpected results (from reference schema):");
588→                    match arrow::util::pretty::pretty_format_batches(&ref_batches) {
589→                        Ok(pretty) => eprintln!("{pretty}"),
590→                        Err(e) => eprintln!("Failed to format expected batches: {e}"),
591→                    }
592→                    eprintln!("\nActual results:");
593→                    match arrow::util::pretty::pretty_format_batches(batches) {
594→                        Ok(pretty) => eprintln!("{pretty}"),
595→                        Err(e) => eprintln!("Failed to format actual batches: {e}"),
596→                    }
597→                    eprintln!();
598→                    return Err(anyhow::anyhow!(
599→                        "Query reference validation failed: {validation_reason:?}"
600→                    ));
601→                }
602→            }
603→
604→            // Also validate using existing validation logic (TPCH or custom validation data)
605→            let validation_result = self.validate_query_results(query, batches)?;
606→
607→            if let QueryValidationResult::Fail(validation_reason) = validation_result {
608→                eprintln!(
609→                    "\n{} FAIL - Worker {} - Query '{}' validation failed",
610→                    chrono::Utc::now(),
611→                    self.id,
612→                    query.name
613→                );
614→                eprintln!("Query SQL: {}", query.sql);
615→                eprintln!("Validation failure reason: {validation_reason:?}");
616→
617→                // Print expected results based on validation source
618→                if let Some(validation_data) = &self.validation_data
619→                    && let Some(expected_batches) = validation_data.get(&query.name)
620→                {
621→                    eprintln!("\nExpected results (from custom validation data):");
622→                    match arrow::util::pretty::pretty_format_batches(expected_batches) {
623→                        Ok(pretty) => eprintln!("{pretty}"),
624→                        Err(e) => eprintln!("Failed to format expected batches: {e}"),
625→                    }
626→                } else {
627→                    eprintln!(
628→                        "\nExpected results: See TPCH specification for query {}",
629→                        query.name
630→                    );
631→                }
632→
633→                eprintln!("\nActual results:");
634→                match arrow::util::pretty::pretty_format_batches(batches) {
635→                    Ok(pretty) => eprintln!("{pretty}"),
636→                    Err(e) => eprintln!("Failed to format actual batches: {e}"),
637→                }
638→                eprintln!();
639→
640→                return Err(anyhow::anyhow!(
641→                    "Query validation failed: {validation_reason:?}"
642→                ));
643→            }
644→        }
645→
646→        // Handle result snapshots if requested
647→        if results_snapshot && let Some(batches) = &result.batches {
648→            let query_name = Arc::clone(&query.name);
649→            let name = self.name.clone();
650→            let snapshot_name = if (self.scale_factor - 1.0).abs() < f64::EPSILON {
651→                format!("{name}_{query_name}")
652→            } else {
653→                format!("{name}_{query_name}_sf{}", self.scale_factor)
654→            };
655→
656→            // Limit to first 10 rows for snapshot
657→            let mut limited_records = vec![];
658→            for batch in batches {
659→                if limited_records.len() >= 10 {
660→                    break;
661→                }
662→                let required_rows = 10 - limited_records.len();
663→                let end = if batch.num_rows() > required_rows {
664→                    required_rows
665→                } else {
666→                    batch.num_rows()
667→                };
668→                for i in 0..end {
669→                    limited_records.push(batch.slice(i, 1));
670→                }
671→            }
672→
673→            let records_pretty = arrow::util::pretty::pretty_format_batches(&limited_records)?;
674→            let result = panic::catch_unwind(|| {
675→                insta::with_settings!({
676→                     description => format!("Query: {query_name}"),
677→                                         omit_expression => true,
678→                    snapshot_path => "../../snapshot/snapshots/results"
679→                }, {
680→                    insta::assert_snapshot!(snapshot_name, records_pretty);
681→                });
682→            });
683→            if result.is_err() {
684→                let error_str = format!("Query `{name}` `{query_name}` snapshot assertion failed",);
685→                eprintln!("{error_str}");
686→                return Err(anyhow::anyhow!(error_str));
687→            }
688→        }
689→
690→        // Check for zero row count if not in skip list
691→        if !self
692→            .skip_row_count_validation
693→            .contains(&query.name.to_string())
694→            && result.row_count == 0
695→        {
696→            eprintln!(
697→                "{} FAIL - Worker {} - Query '{}' returned 0 rows",
698→                chrono::Utc::now(),
699→                self.id,
700→                query.name
701→            );
702→            return Err(anyhow::anyhow!(
703→                "Worker {} - Query '{}' returned 0 rows",
704→                self.id,
705→                query.name
706→            ));
707→        }
708→
709→        // Send streaming metric
710→        self.send_streaming_metric(&query.name, result.duration, true);
711→
712→        // Record metrics
713→        query_durations
714→            .entry(Arc::clone(&query.name))
715→            .or_default()
716→            .push(result.duration);
717→
718→        row_counts
719→            .entry(Arc::clone(&query.name))
720→            .or_default()
721→            .push(result.row_count);
722→
723→        if let Some(pb) = self.progress_bar.as_ref() {
724→            pb.inc(1);
725→        }
726→
727→        Ok(())
728→    }
729→}
