746→/// Build unique query sets by grouping queries by parameter index.
747→/// Creates one query set per parameter variation, where each set contains
748→/// one query of each type with the same parameter index.
749→fn build_unique_query_sets(queries: &[Query]) -> Result<Vec<Vec<Query>>> {
750→    use std::collections::HashMap;
751→
752→    // Group queries by name first
753→    let mut groups: HashMap<Arc<str>, Vec<&Query>> = HashMap::new();
754→    for query in queries {
755→        groups
756→            .entry(Arc::clone(&query.name))
757→            .or_default()
758→            .push(query);
759→    }
760→
761→    // Validate that all groups have the same size
762→    let mut expected_size = None;
763→    for (name, query_group) in &groups {
764→        let group_size = query_group.len();
765→        match expected_size {
766→            None => expected_size = Some(group_size),
767→            Some(expected) if expected != group_size => {
768→                return Err(anyhow::anyhow!(
769→                    "Uneven parameter groups detected: query '{name}' has {group_size} parameters, expected {expected}"
770→                ));
771→            }
772→            _ => {}
773→        }
774→    }
775→
776→    let num_variations = expected_size.unwrap_or(0);
777→
778→    // Create query sets by parameter index
779→    let mut result = Vec::with_capacity(num_variations);
780→
781→    for param_index in 0..num_variations {
782→        let mut query_set = Vec::with_capacity(groups.len());
783→
784→        for query_group in groups.values() {
785→            if let Some(query) = query_group.get(param_index) {
786→                query_set.push((*query).clone());
787→            }
788→        }
789→
790→        result.push(query_set);
791→    }
792→
793→    Ok(result)
794→}
